def state_image(slug, filename=None):
    return STATE_COVER_IMAGES.get(slug) or STATE_COVER_IMAGE


def place_image(slug):
    return PLACE_IMAGE_PATHS.get(slug, f'/assets/places/{slug}.jpg')


