    places = [
        (1, 1, 'fort-kochi', 'Fort Kochi', 'Walk through a coastal neighbourhood shaped by maritime trade, historic streets and public waterfront spaces.', 'culture', 9.9658, 76.2421, 'Reach Kochi by rail or air, then continue by local bus, taxi or ferry where available.', 'This is a neighbourhood, not a single ticketed attraction. Check individual venues separately.', None, 'https://www.keralatourism.org/', place_image('fort-kochi')),
        (2, 1, 'mattancherry-palace', 'Mattancherry Palace', 'Discover Kerala murals and the history of Kochi’s royal household.', 'heritage', 9.9583, 76.2594, 'Continue from central Kochi to Mattancherry by local transport.', 'Museum opening days and ticket rates should be checked before visiting.', None, 'https://www.keralatourism.org/', place_image('mattancherry-palace')),
        (3, 2, 'alappuzha-backwaters', 'Alappuzha Backwaters', 'Explore the canals and waterways around Alappuzha with a locally operated boat trip.', 'nature', 9.5010, 76.3500, 'Alappuzha railway station connects to the town; boat departure points vary by operator.', 'Coordinate is an approximate town-area starting point. Agree on route and price before booking.', None, 'https://www.keralatourism.org/', place_image('alappuzha-backwaters')),
        (4, 2, 'alappuzha-beach', 'Alappuzha Beach', 'Spend an evening on the coast near Alappuzha town.', 'beach', 9.4929, 76.3177, 'Take local transport from Alappuzha town or railway station.', 'Follow local swimming restrictions and sea-condition advice.', None, 'https://www.keralatourism.org/', place_image('alappuzha-beach')),
        (5, 3, 'amber-fort', 'Amber Fort', 'Explore courtyards, gateways and hilltop architecture at a component of the Hill Forts of Rajasthan World Heritage property.', 'heritage', 26.9855, 75.8513, 'Travel 11 km from Jaipur to Amer by bus, auto-rickshaw or taxi.', 'Open daily 8:00 AM to 5:30 PM, evening light show 6:30 PM. Tickets: ₹100 for Indian nationals, ₹500 for foreign visitors (composite tickets available). Licensed ASI guides at Suraj Pol gate. Elephant rides operate 8:00–11:00 AM only; walking or jeep taxi up the cobbled ramp recommended. Last verified: October 2026.', 1, 'https://www.tourism.rajasthan.gov.in/jaipur.html', place_image('amber-fort')),
        (6, 3, 'jantar-mantar', 'Jantar Mantar, Jaipur', 'Explore monumental astronomical instruments at this UNESCO World Heritage Site.', 'heritage', 26.9248, 75.8246, 'Located in Jaipur’s old city adjacent to City Palace.', 'Open daily 9:00 AM to 5:00 PM. Tickets: ₹50 for Indian nationals, ₹200 for foreign visitors. Audio guides and authorized local guides explain the functioning of the Samrat Yantra and zodiac dials. Best visited in midday for clear solar shadow readings. Last verified: October 2026.', 2, 'https://whc.unesco.org/en/list/1338/', place_image('jantar-mantar')),
        (7, 4, 'jaisalmer-fort', 'Jaisalmer Fort', 'Walk through a living sandstone fort that forms part of the Hill Forts of Rajasthan World Heritage property.', 'heritage', 26.9124, 70.9120, 'Reach Jaisalmer by rail or road, then continue on foot or auto-rickshaw to the fort gates.', 'Open daily 6:00 AM to 5:00 PM. Palace museum entry: ₹100 for Indians, ₹250 for foreign visitors. Respect the 3,000 residents living inside the fort precinct. Narrow cobblestone alleys best explored on foot. Last verified: October 2026.', 1, 'https://www.tourism.rajasthan.gov.in/jaisalmer.html', place_image('jaisalmer-fort')),
        (8, 4, 'gadisar-lake', 'Gadisar Lake', 'Visit a historic water body framed by gateways and small shrines near Jaisalmer.', 'nature', 26.9083, 70.9232, 'A short local journey from Jaisalmer’s old town.', 'Visit early or late in the day; boat services depend on local conditions.', None, 'https://www.tourism.rajasthan.gov.in/jaisalmer.html', place_image('gadisar-lake')),
        (9, 5, 'basilica-bom-jesus', 'Basilica of Bom Jesus', 'Visit the historic basilica in Old Goa, part of the Churches and Convents of Goa World Heritage property.', 'heritage', 15.5009, 73.9116, 'Reach Old Goa from Panaji by bus, taxi or other local transport.', 'Respect the active religious setting and check visitor arrangements.', 3, 'https://www.goa-tourism.com/', place_image('basilica-bom-jesus')),
        (10, 5, 'fontainhas', 'Fontainhas', 'Walk through Panaji’s Latin Quarter, known for colourful façades and old streets.', 'culture', 15.4958, 73.8278, 'Located in central Panaji and accessible by local transport.', 'Use a quiet walking route and respect residential streets.', None, 'https://www.goa-tourism.com/', place_image('fontainhas')),
        (11, 6, 'palolem-beach', 'Palolem Beach', 'A curved South Goa beach with a relaxed coastal atmosphere and seasonal activities.', 'beach', 15.0100, 74.0232, 'Reach Canacona by rail or road, then continue locally to the beach.', 'Beach conditions and seasonal businesses change; follow local safety advice.', None, 'https://www.goa-tourism.com/', place_image('palolem-beach')),
        (12, 6, 'dudhsagar-falls', 'Dudhsagar Falls', 'A dramatic waterfall landscape in the Western Ghats, best planned with current access information.', 'nature', 15.3144, 74.3144, 'Access rules and permitted routes vary; check the official forest/tourism guidance first.', 'Do not enter restricted areas. Monsoon access and water conditions can change quickly.', None, 'https://www.goa-tourism.com/', place_image('dudhsagar-falls')),
        (13, 7, 'shimla-ridge', 'The Ridge, Shimla', 'A broad hilltop promenade with mountain views and a close connection to Shimla’s public life.', 'culture', 31.1048, 77.1734, 'Shimla is connected by road; the historic Kalka-Shimla mountain railway route reaches nearby areas.', 'Open 24 hours. Free public pedestrian access; motor vehicles strictly prohibited. Walking in the hill town involves slopes and steps. Connects directly to Mall Road, Lakkar Bazaar, and Christ Church (1857). Last verified: October 2026.', None, 'https://himachaltourism.gov.in/destination/shimla/', place_image('shimla-ridge')),
        (14, 7, 'jakhu-temple', 'Jakhu Temple', 'A hilltop temple reached through Shimla’s wooded slopes, with broad views over the town.', 'spiritual', 31.1046, 77.1820, 'Continue from Shimla by local taxi or on foot where appropriate.', 'Follow temple customs and take care around steep paths and local wildlife.', None, 'https://himachaltourism.gov.in/destination/shimla/', place_image('jakhu-temple')),
        (15, 8, 'dharamshala', 'Dharamshala', 'A mountain destination connecting Tibetan cultural life, hillside walks and Dhauladhar views.', 'nature', 32.2190, 76.3234, 'Reach by road or via Kangra airport, then use local transport between settlements.', 'The area spans different elevations; allow time for weather and road changes.', None, 'https://himachaltourism.gov.in/', place_image('dharamshala')),
        (16, 8, 'masroor-temple', 'Masroor Rock-Cut Temples', 'Explore a remarkable group of temples carved from rock in the Kangra landscape.', 'heritage', 32.0108, 76.0907, 'Plan a road journey from Kangra or Dharamshala and check local access.', 'Treat this as a heritage site; avoid climbing or touching carved surfaces.', None, 'https://himachaltourism.gov.in/', place_image('masroor-temple')),
        (17, 9, 'marina-beach', 'Marina Beach', 'See Chennai’s long urban shoreline and the city’s evening public life.', 'beach', 13.0500, 80.2824, 'Accessible from central Chennai by local bus, rail or taxi.', 'The sea can be dangerous; follow local warnings and do not assume swimming is safe.', None, 'https://www.tamilnadutourism.com/', place_image('marina-beach')),
        (18, 9, 'kapaleeshwarar-temple', 'Kapaleeshwarar Temple', 'Visit a major Chennai temple surrounded by the streets and food culture of Mylapore.', 'spiritual', 13.0338, 80.2697, 'Reach Mylapore by local bus, rail or taxi.', 'Check temple visitor customs and opening hours before visiting.', None, 'https://www.tamilnadutourism.com/', place_image('kapaleeshwarar-temple')),
        (19, 10, 'meenakshi-temple', 'Meenakshi Amman Temple', 'Explore the temple complex and living streets of Madurai’s historic centre.', 'spiritual', 9.9195, 78.1193, 'Madurai is connected by air, rail and road; the temple is in the city centre.', 'Follow photography and dress guidance issued at the temple.', None, 'https://www.tamilnadutourism.com/', place_image('meenakshi-temple')),
        (20, 10, 'thirumalai-nayak-palace', 'Thirumalai Nayak Palace', 'See the monumental court architecture of a seventeenth-century palace in Madurai.', 'heritage', 9.9145, 78.1193, 'A short local journey from Meenakshi Temple and central Madurai.', 'Check current light-and-sound schedules separately from daytime access.', None, 'https://www.tamilnadutourism.com/', place_image('thirumalai-nayak-palace')),
        (21, 27, 'konark-sun-temple', 'Konark Sun Temple', 'Marvel at the 13th-century Sun Temple designed as a colossal chariot with intricately carved stone wheels and horses. A UNESCO World Heritage property on the Bay of Bengal coast.', 'heritage', 19.8876, 86.0945, 'Located 35 km from Puri and 65 km from Bhubaneswar; easily reached by road via Marine Drive.', 'Open sunrise to sunset. Ticketed entry (ASI monument). Visit during early morning or late afternoon for golden hour photography.', 4, 'https://whc.unesco.org/en/list/246/', place_image('konark-sun-temple')),
        (22, 27, 'puri-jagannath-temple', 'Shree Jagannath Temple, Puri', 'One of India’s four holy Char Dham pilgrimage sites, this monumental 12th-century temple is dedicated to Lord Jagannath, Balabhadra and Subhadra. Renowned for its towering shikhara, massive kitchen serving Mahaprasad, and the world-famous Rath Yatra.', 'spiritual', 19.8049, 85.8179, 'Located in the heart of Puri town; connected by rail and a 60 km expressway from Bhubaneswar airport.', 'Strict dress and entry protocols apply. Electronic devices and leather items must be deposited outside. Don\'t miss tasting the sacred Ananda Bazar Mahaprasad.', None, 'https://odishatourism.gov.in/', place_image('puri-jagannath-temple')),
        (23, 27, 'chilika-lake', 'Chilika Lake', 'Asia’s largest brackish water lagoon, a Ramsar wetland sanctuary home to endangered Irrawaddy dolphins and a winter haven for over a million migratory birds from Siberia and Central Asia.', 'nature', 19.7167, 85.3167, 'Major boat boarding points are at Satapada (50 km from Puri) and Barkul / Rambha along NH-16.', 'Early morning boat rides offer the best chances of dolphin sightings near Satapada and bird watching around Mangalajodi wetlands.', None, 'https://odishatourism.gov.in/', place_image('chilika-lake')),
        (24, 28, 'lingaraj-temple', 'Lingaraj Temple, Bhubaneswar', 'The crowning jewel of Kalinga architecture in Bhubaneswar, the 11th-century Lingaraj Temple rises 55 metres over the old town. Dedicated to Harihara, it is surrounded by over 150 smaller shrines and the sacred Bindu Sagar tank.', 'heritage', 20.2382, 85.8336, 'Located in the Old Town area of Bhubaneswar, easily reached by auto-rickshaw or taxi from anywhere in the capital.', 'A viewing platform is located near the northern perimeter wall offering panoramas of the temple courtyards for visitors.', None, 'https://odishatourism.gov.in/', place_image('lingaraj-temple')),
        (25, 5, 'aguada-fort', 'Fort Aguada & Lighthouse', 'A monumental 17th-century Portuguese fortress and four-tiered lighthouse overlooking the Arabian Sea and the mouth of the Mandovi River. Built in 1612 with a massive 79-gun battery and a 2.3-million-gallon freshwater cistern that once replenished passing merchant ships.', 'heritage', 15.4925, 73.7736, 'Located in Sinquerim, Candolim; approximately 15 km from Panaji. Easily accessible by taxi, auto-rickshaw, or rented two-wheeler along the coastal road.', 'Open daily 9:30 AM to 6:00 PM. Ticketed entry through ASI. Carry water and sun protection when walking along the upper battlements. Stunning sunset views over the Arabian Sea.', None, 'https://www.goa-tourism.com/', place_image('aguada-fort')),
        (26, 5, 'se-cathedral', 'Se Cathedral, Old Goa', 'One of the largest churches in Asia and part of the UNESCO World Heritage Churches and Convents of Goa. Dedicated to St. Catherine of Alexandria, it features magnificent Tuscan-Manueline architecture, gilded Corinthian altars, and the famous Golden Bell known for its rich acoustic resonance.', 'heritage', 15.5039, 73.9122, 'Located in Old Goa (Velha Goa), 10 km east of Panaji. Reachable via NH-748 by local bus, taxi or rental vehicle.', 'Open daily 7:30 AM to 6:00 PM. Free entry. Modest attire covering shoulders and knees is strictly required for entry. Photography is restricted inside the active prayer sanctuary.', 3, 'https://whc.unesco.org/en/list/234/', place_image('se-cathedral')),
        (27, 5, 'anjuna-beach', 'Anjuna Beach', 'A legendary coastline framed by volcanic red laterite cliffs, swaying coconut groves, and sea-facing rocky headlands. Known globally for its counter-culture history, the bustling Wednesday Flea Market, sunset drum circles, and open-air beachfront cafes.', 'beach', 15.5733, 73.7410, 'Situated in Bardez taluka, about 18 km from Panaji and 8 km from Mapusa. Best explored on a rented scooter or via coastal taxis.', 'Swimming requires caution due to underwater laterite rock formations; swim only in designated lifeguard-patrolled zones. The Wednesday flea market operates from morning till sunset.', None, 'https://www.goa-tourism.com/', place_image('anjuna-beach')),
        (28, 6, 'mangueshi-temple', 'Shree Manguesh Temple, Priol', 'A 450-year-old architectural gem nestled among lush forested hills in Ponda. Dedicated to Lord Manguesh (an incarnation of Shiva), the temple features a distinctive seven-story octagonal deepstambha (lamp tower), sparkling Sabha Griha chandeliers, and a sacred water tank.', 'spiritual', 15.4419, 73.9686, 'Located in Priol, Ponda taluka, along the Panaji–Ponda highway (21 km from Panaji, 26 km from Margao). Readily connected by state buses and taxis.', 'Open daily 6:00 AM to 9:00 PM. Dress code is strictly traditional/modest. Leather items and footwear must be deposited at the outer gate before entering the courtyard.', None, 'https://www.goa-tourism.com/', place_image('mangueshi-temple')),
        (29, 6, 'cabo-de-rama-fort', 'Cabo de Rama Fort', 'A wild, evocative coastal clifftop fortress standing high above the Arabian Sea at the southern promontory of Canacona. Rich in legend as the sanctuary where Lord Rama and Sita stayed during their fourteen-year exile, with ancient stone ramparts, historic cannons, and the charming whitewashed Church of St. Antonio.', 'heritage', 15.0898, 73.9219, 'Located 30 km south of Margao and 18 km north of Palolem. Accessible via winding scenic rural roads by car, taxi or rented scooter.', 'Open daily 9:00 AM to 5:30 PM. Free entry. The clifftop drops sheer to the sea below—exercise care near the cliff edges. Unmatched 360-degree panoramic ocean views at sunset.', None, 'https://www.goa-tourism.com/', place_image('cabo-de-rama-fort')),
        (30, 6, 'shanta-durga-temple', 'Shanta Durga Temple, Kavlem', 'One of Goa’s largest and most revered Hindu pilgrimage shrines, dedicated to Goddess Shanta Durga, the peaceful mediator between Lord Shiva and Lord Vishnu. Set in a verdant valley in Ponda with a striking five-tiered deepstambha, a golden palanquin, and terracotta tile roofs blending Konkani and Portuguese design elements.', 'spiritual', 15.3942, 73.9856, 'Located at the foothills of Kavlem in Ponda taluka, 28 km from Panaji and 18 km from Margao. Direct road access via Ponda city.', 'Open daily 6:00 AM to 8:30 PM. Follow temple dress etiquette. The annual Jatra festival in Magha (January/February) features elaborate temple chariot processions.', None, 'https://www.goa-tourism.com/', place_image('shanta-durga-temple')),
        (31, 6, 'agonda-beach', 'Agonda Beach', 'A serene and uncommercialised 3-kilometre expanse of pristine golden sand fringed by palm groves and gentle surf. Designated as a protected eco-sensitive nesting site for Olive Ridley sea turtles, ideal for quiet coastal walks, yoga retreats, and dolphin watching in calm morning waters.', 'beach', 15.0442, 73.9878, 'Located in Canacona taluka, 70 km south of Dabolim airport and 10 km north of Palolem Beach. Connected by rural bus and local taxi services.', 'Strict silent-beach regulations are enforced at night to protect nesting turtles. Boat trips for dolphin spotting can be arranged from local fishers in the morning.', None, 'https://www.goa-tourism.com/', place_image('agonda-beach')),
        (32, 29, 'tsomgo-lake', 'Tsomgo Lake (Changu Lake)', 'A sacred glacial alpine lake sitting at 3,753 metres (12,313 ft) in the East Himalayas, framed by rugged snow-dusted peaks. Revered by local Buddhist monks for centuries, the lake remains frozen in winter and is surrounded by blooming alpine rhododendrons and primulas in spring and summer.', 'nature', 27.3742, 88.7619, 'Located 40 km northeast of Gangtok along Jawaharlal Nehru Road toward Nathu La. Reachable by shared or private four-wheel-drive taxis from Gangtok.', 'A Protected Area Permit (PAP) is mandatory for all visitors, obtainable through registered Sikkim travel agents in Gangtok. Acclimatise properly due to the high altitude.', None, 'https://www.sikkimtourism.gov.in/', place_image('tsomgo-lake')),
        (33, 33, 'rumtek-monastery', 'Rumtek Monastery', 'The premier seat-in-exile of the Gyalwang Karmapa, head of the Karma Kagyu lineage of Tibetan Buddhism. Rebuilt in the 1960s as a replica of Tsurphu Monastery in Tibet, the grand complex features magnificent Tibetan religious murals, golden stupas holding sacred relics, intricate thangkas, and a monastic college.', 'spiritual', 27.3039, 88.5475, 'Situated 24 km southwest of Gangtok on the opposite hillside; easily accessible by taxi or local bus via the Ranipool-Rumtek road.', 'Open daily 6:00 AM to 6:00 PM. Visitors must present photo ID at the entrance gate. Photography is restricted inside the main prayer hall. The early morning chanting ceremony is deeply meditative.', None, 'https://www.sikkimtourism.gov.in/', place_image('rumtek-monastery')),
        (34, 31, 'gurudongmar-lake', 'Gurudongmar Lake', 'One of the highest lakes in the world, sitting at a staggering elevation of 5,430 metres (17,800 ft) amidst the barren, windswept Tibetan plateau. Blessed by Guru Padmasambhava and Guru Nanak, a portion of the crystal-clear azure waters remains miraculously unfrozen even during harsh sub-zero Himalayan winters.', 'nature', 28.0258, 88.7089, 'Located in North Sikkim, 175 km from Gangtok via Mangan, Chungthang, and Lachen. Requires a two-day journey with an overnight halt at Lachen village.', 'Special Protected Area Permit (PAP) required. Open only to Indian nationals due to proximity to the international border. Extremely low oxygen levels—consult a physician before visiting and leave early morning before high winds start.', None, 'https://www.sikkimtourism.gov.in/', place_image('gurudongmar-lake')),
        (35, 31, 'yumthang-valley', 'Yumthang Valley of Flowers', 'A spectacular alpine grazing meadow at 3,564 metres (11,693 ft), surrounded by the snow-capped Himalayan peaks of the Shingba Rhododendron Sanctuary. In spring, the valley carpet erupts in a riot of colours with over 24 species of wild rhododendrons, primulas, and irises, accompanied by natural sulfur hot springs and grazing yaks.', 'nature', 27.8286, 88.6947, 'Located 140 km from Gangtok via Lachung village. Typically visited on a 2-day/1-night trip with base camp at Lachung.', 'Best visited from April to June for wildflowers, or December to February for thick snow. Permits are required and issued in Gangtok.', None, 'https://www.sikkimtourism.gov.in/', place_image('yumthang-valley')),
        (36, 30, 'pemayangtse-monastery', 'Pemayangtse Monastery', 'Founded in 1705 by Lama Lhatsun Chempo, Pemayangtse is one of Sikkim’s oldest, most prestigious Nyingma Buddhist monasteries. Perched at 2,085 metres, it commands panoramic views of Mount Kangchenjunga and houses the legendary seven-tiered wooden masterpiece depicting Guru Padmasambhava’s celestial palace, Sangthokpalri.', 'spiritual', 27.3047, 88.2528, 'Located 2 km from Pelling and 110 km from Gangtok via Ravangla. Well connected by shared and private taxis from Pelling town.', 'Open daily 9:00 AM to 6:00 PM. Modest dress required. The ancient Rabdentse Palace ruins are located within a scenic 15-minute forested walk from the monastery gate.', None, 'https://www.sikkimtourism.gov.in/', place_image('pemayangtse-monastery')),
        (37, 32, 'solophok-char-dham', 'Siddhesvara Dhaam (Char Dham), Namchi', 'A grand pilgrimage and cultural complex atop Solophok Hill in southern Sikkim, featuring a colossal 108-foot statue of Lord Shiva seated above a temple with twelve Jyotirlinga shrines. The complex also features authentic scaled replicas of India’s four sacred Char Dham temples set against breathtaking Himalayan vistas.', 'heritage', 27.1642, 88.3375, 'Located 5 km from Namchi town and 78 km from Gangtok. Accessible by taxi or bus via the Namchi-Melli highway.', 'Open daily 6:30 AM to 8:30 PM. Wheelchair accessible with paved walkways, vegetarian dining facilities, musical fountain evening shows, and extensive parking.', None, 'https://www.sikkimtourism.gov.in/', place_image('solophok-char-dham')),
        (38, 31, 'khangchendzonga-national-park', 'Khangchendzonga National Park', 'India’s only Mixed UNESCO World Heritage Site, covering an extraordinary altitudinal range from subtropical valleys to the snow-capped summit of Mount Kangchenjunga (8,586 m, the world’s third-highest peak). Revered in Sikkimese culture as a sacred Beyul (hidden holy land), it shelters rare Himalayan wildlife including the snow leopard and red panda.', 'heritage', 27.7000, 88.1500, 'Trekking entry points begin at Yuksom in Gyalshing district or Lachen in Mangan district. Reached by road from Gangtok to Yuksom (125 km).', 'UNESCO World Heritage inscribed property. Trekking requires prior forest department permits, certified local guides, and proper mountaineering gear. Best trekking seasons are March-May and October-November.', 5, 'https://whc.unesco.org/en/list/1513/', place_image('khangchendzonga-national-park')),
        (39, 35, 'ujjayanta-palace', 'Ujjayanta Palace & State Museum', 'The magnificent neoclassical royal palace of the Manikya dynasty, built in 1901 by Maharaja Radha Kishore Manikya and named by Nobel laureate Rabindranath Tagore. Set amidst 28 hectares of Mughal-inspired gardens and twin artificial lakes, the palace now houses the largest museum in Northeast India showcasing Tripura’s royal artifacts, tribal crafts, and archaeological treasures.', 'heritage', 23.8344, 91.2825, 'Located in the heart of Agartala. Easily accessible by auto-rickshaw, cycle rickshaw, or taxi from anywhere in the city. Agartala Airport is 10 km away.', 'Open Tuesday to Sunday 10:00 AM to 5:00 PM (closed on Mondays). Ticketed entry. Evening musical fountain shows operate on weekends.', None, 'https://tripuratourism.gov.in/', place_image('ujjayanta-palace')),
        (40, 37, 'neermahal-water-palace', 'Neermahal (Water Palace), Melaghar', 'The only lake palace in Eastern India, built in 1930 by Maharaja Bir Bikram Kishore Manikya as his summer residence in the middle of the vast Rudrasagar Lake (a Ramsar wetland). Featuring a harmonious blend of Hindu and Mughal architectural domes, towers, and pavilions, the palace is reached via scenic motorboat across the sparkling lake waters.', 'heritage', 23.4939, 91.3197, 'Located in Melaghar, 53 km south of Agartala. Connected by regular state buses and private taxis from Agartala.', 'Open daily 9:00 AM to 5:00 PM. Reached by government and private motorboats from the Rajghat boat jetty. The annual Neermahal Water Festival in August/September features exciting boat race competitions.', None, 'https://tripuratourism.gov.in/', place_image('neermahal-water-palace')),
        (41, 38, 'unakoti-rock-carvings', 'Unakoti Rock-Cut Heritage Site', 'An awe-inspiring Shaivite pilgrimage sanctuary dating to the 7th–9th centuries, set amidst a deep forested gorge. Literally meaning \'one less than a crore\' (99,99,999), the site features colossal rock-cut bas-relief carvings including the 30-foot central head of Lord Shiva (Unakotiswara Kal Bhairava), monumental Ganesha figures, and cascading jungle waterfalls on UNESCO\'s tentative World Heritage list.', 'heritage', 24.3167, 92.0667, 'Located 8 km from Kailashahar town and 178 km from Agartala. Nearest railway station is Kumarghat (20 km away).', 'ASI protected heritage monument. Open sunrise to sunset. Wear comfortable walking shoes as the site involves climbing stone steps down into the gorge. The grand Ashokastami Mela is celebrated here in April.', 9, 'https://whc.unesco.org/en/tentativelists/6628/', place_image('unakoti-rock-carvings')),
        (42, 36, 'tripura-sundari-temple', 'Tripura Sundari Temple (Matabari), Udaipur', 'One of the 51 holy Shakti Peethas, where the right foot of Goddess Sati is believed to have fallen. Built in 1501 AD by Maharaja Dhanya Manikya, the square sanctum is designed in the distinctive Bengali Kurma (tortoise-shaped) Chala style. The sacred Kalyan Sagar lake behind the temple shelters endangered Bostami softshell giant freshwater turtles.', 'spiritual', 23.5117, 91.4994, 'Located in Udaipur, 55 km from Agartala. Frequent trains and buses connect Agartala with Udaipur railway station (3 km from the temple).', 'Open daily 5:00 AM to 9:00 PM. Footwear must be deposited at the outer entrance. Peda sweets offered as prasad are famous. The annual Diwali Mela draws over two hundred thousand devotees.', None, 'https://tripuratourism.gov.in/', place_image('tripura-sundari-temple')),
        (43, 36, 'chabimura-rock-carvings', 'Chabimura Rock Carvings, Amarpur', 'Famous as the \'Amazon of Tripura\', Chabimura features colossal 15th-century rock-cut carvings of Goddess Mahishasuramardini (Durga) and Lord Shiva sculpted directly onto the towering vertical sandstone cliffs along the banks of the Gomati River, surrounded by dense virgin subtropical rainforest.', 'nature', 23.5350, 91.6850, 'Located near Amarpur in Gomati district, about 82 km from Agartala. Accessible by boat ride up the Gomati river from the Amarpur boat jetty.', 'Reached via guided motorboat safari through the river gorge. Best visited between October and April when water levels are calm and clear. Carry sun protection and insect repellent.', None, 'https://tripuratourism.gov.in/', place_image('chabimura-rock-carvings')),
        (44, 39, 'jampui-hills', 'Jampui Hills (Land of Eternal Spring)', 'The highest mountain range in Tripura (rising to 3,200 ft at Betlingchhip peak), bordering Mizoram. Famed as the \'Land of Eternal Spring\' for its cool year-round climate, fragrant orange and betel nut orchards, tranquil Mizo tribal villages (Vanghmun), and panoramic vantage points offering sunrise views across the Chittagong Hill Tracts.', 'nature', 23.9500, 92.2833, 'Located 200 km from Agartala via Dharmanagar (65 km from Dharmanagar). Well connected by road; state transport buses and private shared jeeps operate from Dharmanagar.', 'Tourism department tourist lodges are available at Vanghmun. The annual Orange & Tourism Festival in November/December is the prime cultural celebration.', None, 'https://tripuratourism.gov.in/', place_image('jampui-hills')),
        (45, 40, 'pilak-archaeological-site', 'Pilak Archaeological Site, Jolaibari', 'A fascinating historical crossroads dating from the 8th to 12th centuries, showcasing the peaceful coexistence of Buddhist and Hindu traditions. Excavated stupas, terracotta plaques, and colossal sandstone statues of Avalokiteshvara, Buddha, Surya, and Mahishasuramardini reflect a remarkable fusion of Pala and indigenous Arakanese art.', 'heritage', 23.1833, 91.5667, 'Located in Jolaibari, 100 km south of Agartala and 30 km from Belonia. Accessible by road via NH-8.', 'Maintained by the Archaeological Survey of India (ASI). Open daily sunrise to sunset. An annual archaeological and cultural festival is organised here every winter.', None, 'https://tripuratourism.gov.in/', place_image('pilak-archaeological-site')),
        (46, 41, 'dumboor-lake', 'Dumboor Lake, Gandacherra', 'A breathtaking water body spanning 41 square kilometres at the confluence of the Raima and Sarma rivers, forming the source of the Gomati River. Shaped like Lord Shiva’s small drum (Dambur), the lake is dotted with 48 emerald-green hillock islands, vibrant winter migratory waterbirds, and scenic boat safaris.', 'nature', 23.4500, 91.8000, 'Located in Dhalai district near Amarpur/Gandacherra, 120 km from Agartala. Reachable by road via Amarpur or Ambassa.', 'Motorboats and paddle boats are available for island exploration. Water sports facilities and eco-cottages operate on Narkel Kunja island. The sacred Tirthamukh pilgrimage site is adjacent.', None, 'https://tripuratourism.gov.in/', place_image('dumboor-lake')),
        (47, 43, 'hidimba-devi-temple', 'Hidimba Devi Temple, Manali', 'An extraordinary 1553 AD pagoda-style wooden temple dedicated to Hidimba Devi, wife of Bhima from the Mahabharata. Nestled inside a dense sanctuary of towering deodar cedar trees (Dhungari Van Vihar), the temple features three tiered wooden roofs crowned with a brass cone, intricate wooden carvings of animals and deities, and wooden door lintels.', 'spiritual', 32.2483, 77.1811, 'Located 2.5 km from Manali town center (Mall Road). Easily accessible on foot or by auto-rickshaw/taxi through Dhungari.', 'Open daily 8:00 AM to 6:00 PM. Free entry. Footwear must be removed at the wooden threshold. Beautiful walking trails lead through the surrounding deodar forest. Last verified: October 2026.', None, 'https://himachaltourism.gov.in/', place_image('hidimba-devi-temple')),
        (48, 43, 'rohtang-pass', 'Rohtang Pass & Solang Valley', 'A legendary high-altitude mountain pass at 3,978 metres (13,058 ft) on the Pir Panjal range, connecting the lush Kullu Valley with the arid high-altitude Lahaul and Spiti valleys. Offering breathtaking 360-degree panoramas of snow-capped peaks, glaciers, and cascading waterfalls.', 'nature', 32.3716, 77.2466, 'Located 51 km north of Manali along the Leh-Manali Highway. Solang Valley is 14 km from Manali. Accessible by licensed tourist taxis from Manali.', 'Seasonally open from late May/June to mid-November (strictly closed by heavy snow rest of year). Mandatory online NGT vehicle permit required. Closed on Tuesdays for maintenance. High-altitude mountain weather changes rapidly. Last verified: October 2026.', None, 'https://himachaltourism.gov.in/', place_image('rohtang-pass')),
        (49, 45, 'key-monastery', 'Key Monastery (Kye Gompa), Spiti', 'A dramatic 1,000-year-old Tibetan Buddhist monastery perched fort-like atop a conical hill at 4,166 metres (13,668 ft) overlooking the Spiti River. The largest monastery in Spiti and a prime training center for lamas of the Gelugpa sect, featuring ancient prayer halls, sacred thangkas, manuscripts, and monks\' quarters.', 'spiritual', 32.2981, 78.0125, 'Located 14 km north of Kaza in Spiti Valley. Reachable by taxi or local bus from Kaza town.', 'Open daily 6:00 AM to 6:00 PM. Free entry. High altitude (4,166 m)—take time ascending stone stairways. Respect prayer halls and silence during morning puja. Photography prohibited in inner sanctum. Last verified: October 2026.', None, 'https://himachaltourism.gov.in/', place_image('key-monastery')),
        (50, 45, 'chandratal-lake', 'Chandratal Lake (Lake of the Moon)', 'A crescent-shaped high-altitude glacial lake at 4,250 metres (13,940 ft) in the Spiti Valley near Kunzum Pass. Revered in Hindu mythology as the spot from where Yudhishthira ascended to heaven in his chariot, the crystal-clear waters change colors from turquoise green to sapphire blue throughout the day, framed by the Chandra Bhaga mountain range.', 'nature', 32.4824, 77.6167, 'Located 115 km from Kaza and 140 km from Manali via the Rohtang/Atal Tunnel and Batal. Reached by road up to the parking point followed by a scenic 1.5 km flat trek to the lake shores.', 'Strictly accessible from late June/July to mid-September only (snowbound and road-closed for 9 months). High-altitude pass access requires 4x4 and acclimatization. Camping directly at the lake shore is prohibited (eco-camps operate 3 km before). Last verified: October 2026.', None, 'https://himachaltourism.gov.in/', place_image('chandratal-lake')),
        (51, 45, 'tabo-monastery', 'Tabo Monastery (Ajanta of the Himalayas)', 'Founded in 996 AD by the Buddhist king and scholar Yeshe-Ö, Tabo is the oldest continuously operating Buddhist enclave in India and the Himalayas. Nestled in Spiti at 3,280 m, its nine mud-brick temples house extraordinary 10th-century stucco statues, clay sculptures of the Vairochana cycle, and exquisite wall frescoes on UNESCO\'s tentative World Heritage list.', 'heritage', 32.0928, 78.3844, 'Located in Tabo village, 48 km east of Kaza along the Kaza-Sumdo-Shimla road. Regular bus and taxi services operate from Kaza and Reckong Peo.', 'Open daily 6:00 AM to 5:00 PM (except during monks\' afternoon meditation). Free entry. No flash photography inside mud-brick shrines to preserve ancient murals. On UNESCO tentative list. Last verified: October 2026.', 10, 'https://whc.unesco.org/en/tentativelists/6075/', place_image('tabo-monastery')),
        (52, 46, 'khajjiar-lake', 'Khajjiar (Mini Switzerland of India)', 'A picturesque saucer-shaped alpine meadow at 1,920 metres, cradled by dense deodar cedar forests and overlooked by snow-clad Himalayan ranges. At its center lies Khajjiar Lake with a floating weed island, alongside the 12th-century wooden temple of Khajji Nag adorned with intricate wood carvings depicting the Pandavas.', 'nature', 32.5558, 76.0656, 'Located 24 km from Dalhousie and 22 km from Chamba. Readily accessible by road via taxi or scenic local bus from Dalhousie.', 'Open year-round; meadows are green and blooming from April to October and snow-covered from December to February. Horse riding, nature walks, and Zorbing are available. Last verified: October 2026.', None, 'https://himachaltourism.gov.in/', place_image('khajjiar-lake')),
        (53, 48, 'prashar-lake', 'Prashar Lake & Temple, Mandi', 'A mystical high-altitude lake at 2,730 metres (8,956 ft) surrounded by the Dhauladhar mountain range, featuring a unique circular floating reed island that slowly changes its position throughout the year. On the lake bank stands a three-tiered pagoda-style wooden temple built in the 14th century by Raja Bansen of Mandi, dedicated to Sage Prashar.', 'nature', 31.7547, 77.1008, 'Located 49 km north of Mandi town. Accessible by road via Bagi or Kataula; local taxis and a daily bus service connect Mandi to the lake.', 'The depth of the lake remains unmeasured to this day. Simple temple guesthouse and forest rest house accommodation is available nearby. Beautiful views of the snow-clad Pir Panjal and Dhauladhar ranges. Last verified: October 2026.', None, 'https://himachaltourism.gov.in/', place_image('prashar-lake')),
        (54, 15, 'taj-mahal', 'Taj Mahal, Agra', 'The sublime white marble mausoleum built between 1631 and 1648 by Mughal Emperor Shah Jahan in memory of his favourite wife Mumtaz Mahal. Standing on the southern bank of the Yamuna River, it is an internationally revered masterpiece of symmetry, inlaid semi-precious stones (pietra dura), and Islamic architecture, inscribed as a UNESCO World Heritage Site.', 'heritage', 27.1751, 78.0421, 'Located 200 km from Delhi. High-speed Gatimaan Express and Vande Bharat trains reach Agra Cantt in 100 minutes; the Yamuna Expressway offers a 3-hour drive.', 'Open sunrise to sunset (strictly closed on Fridays). Mandatory pre-booking online via the ASI portal (tickets include shoe covers and water). Large bags, tripods, food, smoking, and drone cameras are prohibited. Sunrise offers the quietest, coolest visiting experience. Last verified: October 2026.', 6, 'https://whc.unesco.org/en/list/252/', place_image('taj-mahal')),
        (55, 21, 'qutub-minar', 'Qutb Minar Complex, Delhi', 'A monumental 72.5-metre-high fluted red and buff sandstone victory tower begun in 1192 by Qutb-ud-din Aibak, marking the start of Muslim rule in Delhi. Surrounded by ancient funerary structures, the Alai Darwaza gateway, Quwwat-ul-Islam mosque, and the legendary 4th-century rust-resistant Gupta iron pillar.', 'heritage', 28.5245, 77.1855, 'Located in Mehrauli, South Delhi. Accessible via Qutab Minar Metro Station on the Yellow Line, followed by a 5-minute auto-rickshaw or 10-minute walk.', 'Open daily sunrise to sunset. Ticketed entry via ASI online portal or QR code at entrance (₹50 Indians, ₹550 foreign visitors). Paved stone walkways with illumination in the evening. Last verified: October 2026.', 7, 'https://whc.unesco.org/en/list/233/', place_image('qutub-minar')),
        (56, 21, 'humayuns-tomb', 'Humayun’s Tomb, Delhi', 'Commissioned in 1558 by Emperor Humayun’s chief consort Empress Bega Begum and designed by Persian architect Mirak Mirza Ghiyas, this majestic red sandstone and white marble garden-tomb was the first grand dynastic mausoleum of the Mughal Empire and the direct architectural precursor to the Taj Mahal.', 'heritage', 28.5933, 77.2507, 'Located in Nizamuddin East, New Delhi. Accessible via JLN Stadium Metro Station (Violet Line) or Hazrat Nizamuddin Railway Station.', 'Open daily sunrise to sunset. Book online on the ASI portal for faster entry. Allow 2 hours to explore the central tomb, Isa Khan’s octagonal tomb, and the renovated Sunder Nursery adjacent. Last verified: October 2026.', 8, 'https://whc.unesco.org/en/list/232/', place_image('humayuns-tomb')),
        (57, 54, 'cellular-jail', 'Cellular Jail National Memorial, Port Blair', 'The infamous colonial prison known as Kālā Pānī, built by the British between 1896 and 1906 to exile Indian freedom fighters and political dissidents. Designed on a panopticon radiating model with seven wings from a central watchtower, it now stands as a sacred national memorial to India\'s freedom struggle.', 'heritage', 11.6738, 92.7478, 'Located at Atlanta Point in Port Blair, 4 km from Veer Savarkar International Airport. Accessible by taxi, auto-rickshaw, or city bus.', 'Open Tuesday to Sunday 9:00 AM to 5:00 PM (closed on Mondays and national holidays). Ticketed entry. The moving sound and light show operates in Hindi and English every evening. Last verified: October 2026.', None, 'https://www.andamantourism.gov.in/', place_image('cellular-jail')),
        (58, 54, 'radhanagar-beach', 'Radhanagar Beach (Beach No. 7), Havelock', 'Crowned repeatedly as one of Asia\'s most spectacular beaches, Radhanagar stretches for over two kilometers on the western coast of Swaraj Dweep (Havelock Island). Famed for powdery white sands, crystal-clear turquoise waters with gentle surf, and an unbroken backdrop of ancient tropical mahua and padauk rainforest trees.', 'beach', 11.9842, 92.9558, 'Reached via government ferry or private catamarans from Port Blair to Havelock (90 mins), then a 20-minute taxi or rented scooter ride across the island.', 'Open sunrise to sunset; swimming is allowed until 5:00 PM under lifeguard supervision. Free entry. Changing rooms, shower facilities, and eco-cafes available. Outstanding sunset viewpoint over the Bay of Bengal. Last verified: October 2026.', None, 'https://www.andamantourism.gov.in/', place_image('radhanagar-beach')),
        (59, 26, 'rock-garden-chandigarh', 'Nek Chand’s Rock Garden, Chandigarh', 'A world-famous 40-acre visionary folk-art sculpture park created secretly over eighteen years by road inspector Nek Chand. Built entirely from industrial and urban domestic waste—broken glass bangles, ceramic tiles, toilet fixtures, discarded electrical plugs, and river stones—arranged into courtyards, narrow gorges, waterfalls, and whimsical armies of dancing figures.', 'culture', 30.7525, 76.8064, 'Located in Sector 1 between Sukhna Lake and the Capitol Complex. Easily reached by auto-rickshaw, cab, or city bus from anywhere in Chandigarh.', 'Open daily 9:00 AM to 7:00 PM (April to September) and 9:00 AM to 6:00 PM (October to March). Tickets: ₹30 for adults, ₹10 for children. Walking involves low doorways, stone steps, and maze-like open-air courtyards. Last verified: October 2026.', None, 'https://chandigarhtourism.gov.in/', place_image('rock-garden-chandigarh')),
        (60, 57, 'diu-fort', 'Diu Fort & Sea Bastions', 'A monumental coastal fortress built in 1535 by the Portuguese following a defense treaty with the Sultan of Gujarat, encircled on three sides by the churning waves of the Arabian Sea and a deep sea moat. Features double stone ramparts, historic brass cannons pointing out to sea, a commanding Venetian-style lighthouse, and sweeping ocean horizons.', 'heritage', 20.7142, 70.9931, 'Located at the eastern tip of Diu Island. Diu has its own airport with flights from Mumbai; nearest broad-gauge railway junction is Veraval (90 km).', 'Open daily 8:00 AM to 6:00 PM. Free entry. Carry drinking water and sunscreen when climbing the sunlit ramparts and lighthouse platform. Outstanding sunset and sunrise photography. Last verified: October 2026.', None, 'https://dnhddtourism.in/', place_image('diu-fort')),
        (61, 58, 'moti-daman-fort', 'Moti Daman Fort & Church of Bom Jesus', 'A polygonal 16th-century Portuguese fortress spanning 30,000 square metres on the southern bank of the Daman Ganga River, protected by a deep moat and ten massive bastions. Enclosed within its ancient stone ramparts is the magnificent 1603 AD Church of Bom Jesus, celebrated for its intricately carved gilded rosewood altar and Manueline doorway.', 'heritage', 20.4147, 72.8331, 'Located in Moti Daman, 12 km from Vapi railway station (on the Mumbai-Ahmedabad mainline). Easily reached by auto-rickshaw or taxi.', 'Open daily 8:00 AM to 6:00 PM. Free entry to fort precinct and church. Modest attire requested inside the active church sanctuary. Beautiful stroll along the riverfront jetty and battlements. Last verified: October 2026.', None, 'https://dnhddtourism.in/', place_image('moti-daman-fort')),
        (62, 60, 'red-fort-delhi', 'Red Fort (Lal Qila), Delhi', 'The colossal octagonal citadel constructed in red sandstone between 1638 and 1648 by Mughal Emperor Shah Jahan as the seat of the Mughal Empire. Inscribed as a UNESCO World Heritage Site, it features the monumental Lahori Gate, Chhatta Chowk bazaar, Diwan-i-Aam (Hall of Public Audience), the exquisite marble Diwan-i-Khas, and the Stream of Paradise (Nahr-i-Bihisht).', 'heritage', 28.6562, 77.2410, 'Located in Old Delhi facing Chandni Chowk. Direct access via Lal Quila Metro Station on the Violet Line or Chandni Chowk on the Yellow Line.', 'Open Tuesday to Sunday sunrise to sunset (closed on Mondays). Pre-booking online via the ASI portal is required (₹50 Indians, ₹550 foreign visitors). High-security screening at Lahori Gate entrance. Allow 2.5–3 hours for exploration. Last verified: October 2026.', 11, 'https://delhitourism.gov.in/', place_image('red-fort-delhi')),
        (63, 21, 'india-gate', 'India Gate & Kartavya Path', 'The monumental 42-metre-high triumphal arch designed by Sir Edwin Lutyens, commemorating 84,000 soldiers of the British Indian Army who died in the First World War. Standing at the eastern terminus of the revitalized Kartavya Path, it features the eternal flame of the National War Memorial, reflecting pools, and illuminated public lawns that form the center of evening public life in the capital.', 'culture', 28.6129, 77.2295, 'Located in Central New Delhi. Reachable via Central Secretariat or Barakhamba Road Metro stations, followed by an auto-rickshaw or short walk.', 'Open 24 hours daily. Free public access. Beautifully illuminated every evening from 7:00 PM to 9:30 PM. Pedestrian underpasses and wide lawns make it ideal for family evening walks. Last verified: October 2026.', None, 'https://delhitourism.gov.in/', place_image('india-gate')),
        (64, 22, 'dal-lake', 'Dal Lake & Mughal Terraces, Srinagar', 'The jewel of Kashmir spanning 18 square kilometers, framed by the soaring Zabarwan and Pir Panjal mountain ranges. Famed for its handcrafted cedarwood houseboats, colourful floating vegetable markets at dawn, gliding shikara gondolas, and the terraced cascades, fountains, and chinars of the historic Mughal Gardens (Shalimar, Nishat, Chashme Shahi) on UNESCO\'s tentative World Heritage list.', 'nature', 34.0837, 74.8732, 'Situated in central Srinagar, 15 km from Sheikh ul-Alam International Airport. Boulevard Road skirts the entire western and northern shorelines.', 'Open year-round. Shikara rides operate from multiple ghats along Boulevard Road (standard government rates apply). The floating vegetable market operates between 5:00 AM and 7:00 AM near Mir Behri. Mughal gardens have a nominal entry fee. Last verified: October 2026.', 12, 'https://jammutourism.jk.gov.in/', place_image('dal-lake')),
        (65, 70, 'gulmarg-gondola', 'Gulmarg Meadow & Mount Apharwat Gondola', 'Known as the "Meadow of Flowers", Gulmarg sits at 2,650 metres in the Pir Panjal range, transforming from an alpine summer wildflower haven into Asia\'s premier deep-powder skiing resort in winter. Home to the Gulmarg Gondola—one of the world\'s highest operating cable cars—transporting visitors in two stages up to 4,000 metres on the snowy shoulder of Mount Apharwat.', 'nature', 34.0484, 74.3805, 'Located 51 km west of Srinagar (approx. 1.5–2 hour drive). Taxis operate from Srinagar to Tangmarg, with snow-chain jeeps required up to Gulmarg during winter months.', 'Gondola operates daily 9:00 AM to 5:00 PM (weather permitting). Phase 1 reaches Kongdori (3,050 m); Phase 2 reaches Apharwat Peak (4,000 m). Gondola tickets must be booked strictly online in advance via the official J&K Cable Car Corporation portal. Warm alpine gear mandatory in winter. Last verified: October 2026.', None, 'https://jammutourism.jk.gov.in/', place_image('gulmarg-gondola')),
        (66, 79, 'vaishno-devi', 'Shri Mata Vaishno Devi Shrine, Katra', 'One of India\'s most revered Hindu pilgrimage sanctuaries, situated in a holy natural cave at an elevation of 1,585 metres in the folds of the sacred Trikuta Mountains. Millions of devotees undertake the 13 km trek from the base camp of Katra to seek the divine blessings of the three natural rock formations (Pindies) representing Mahakali, Mahalakshmi, and Mahasaraswati.', 'spiritual', 33.0308, 74.9490, 'Katra base town has its own major railway station (Shri Mata Vaishno Devi Katra) directly connected to Delhi and major cities. Helicopter services and battery cars operate from Katra to Sanjichhat.', 'Open 24 hours year-round. Yatra registration slip/RFID card is mandatory before commencing the trek (obtainable free online or at Katra counters). The 13 km paved path features illumination, drinking water, medical kiosks, and pony/palki options. Last verified: October 2026.', None, 'https://jammutourism.jk.gov.in/', place_image('vaishno-devi')),
        (67, 71, 'martand-sun-temple', 'Martand Sun Temple, Anantnag', 'The monumental 8th-century stone temple commissioned by the warrior emperor Lalitaditya Muktapida of the Karkota dynasty, dedicated to Surya (the Sun God). Perched atop a high plateau overlooking the entire Kashmir Valley, its majestic colonnaded courtyard, Roman-influenced fluted pillars, and Greek-Gandharan arches stand as an extraordinary pinnacle of classical Kashmiri temple architecture.', 'heritage', 33.7461, 75.2206, 'Located near Mattan, 9 km from Anantnag town and 64 km south of Srinagar along the road toward Pahalgam. Readily accessible by taxi or local bus.', 'ASI protected monument. Open daily sunrise to sunset. Free entry. The plateau offers panoramic views of the Pir Panjal mountains and surrounding apple orchards. Beautiful late-afternoon golden hour light. Last verified: October 2026.', None, 'https://jammutourism.jk.gov.in/', place_image('martand-sun-temple')),
        (68, 24, 'thiksey-monastery', 'Thiksey Monastery (Mini Potala of Ladakh)', 'A spectacular twelve-story Tibetan Buddhist monastery of the Gelugpa (Yellow Hat) order, cascading down a picturesque hill at 3,600 metres overlooking the Indus River valley. Resembling the Potala Palace of Lhasa, it houses ten temples, monks\' quarters, assembly halls, and a famous two-story-high (15-metre) serene statue of Maitreya Buddha installed to commemorate the 1970 visit of the 14th Dalai Lama.', 'spiritual', 34.0577, 77.6669, 'Located 19 km southeast of Leh along the Manali-Leh Highway. Reachable in 30 minutes by taxi or local bus from Leh.', 'Open daily 6:00 AM to 6:00 PM. Modest entry fee (₹50). Visitors are welcomed to witness the atmospheric 7:00 AM morning prayer assembly with deep chanting, conch horns, and cymbals. Modest attire covering shoulders and knees is strictly required. Last verified: October 2026.', None, 'https://ladakh.gov.in/tourism/', place_image('thiksey-monastery')),
        (69, 24, 'pangong-tso', 'Pangong Tso (High Altitude Glacial Lake)', 'An endorheic, high-altitude saline lake sitting at a breathtaking 4,350 metres (14,270 ft) in the Himalayas, spanning 134 km across the Indo-Tibetan border. Famed worldwide for its ever-shifting colours—transitioning from deep emerald green to sparkling azure and cobalt blue against bare terracotta-hued mountain massifs.', 'nature', 33.7595, 78.6674, 'Located 160 km from Leh via the high mountain pass of Chang La (5,360 m). Typically visited as an overnight trip in a private 4x4 taxi from Leh.', 'Inner Line Permit (ILP) is mandatory for domestic travelers; Protected Area Permit (PAP) for foreign nationals, arranged in Leh. Seasonally accessible from May to October (freezes completely solid in winter with sub-zero temperatures down to -30°C). Eco-camps operate at Spangmik village. Last verified: October 2026.', None, 'https://ladakh.gov.in/tourism/', place_image('pangong-tso')),
        (70, 89, 'diskit-monastery', 'Diskit Monastery & Hunder Sand Dunes', 'The oldest and largest Buddhist monastery in the Nubra Valley, founded in the 14th century by Changzem Tserab Zangpo. Perched on a craggy cliff above the floodplains of the Shyok River, it is dominated by an awe-inspiring 32-metre gilded statue of Jampa (Maitreya) Buddha. Nearby at Hunder lie silver cold-desert sand dunes where shaggy double-humped Bactrian camels roam.', 'spiritual', 34.5436, 77.5606, 'Located 120 km north of Leh via the legendary Khardung La pass (5,359 m). Requires a 4x4 or high-clearance vehicle journey of 4–5 hours.', 'Inner Line Permit (ILP) required. Open daily 7:00 AM to 6:00 PM. Double-humped camel safari rides at Hunder dunes operate in morning and late afternoon. Respect monastery dress code. Last verified: October 2026.', None, 'https://ladakh.gov.in/tourism/', place_image('diskit-monastery')),
        (71, 91, 'bangaram-atoll', 'Bangaram Atoll & Coral Reef Lagoon', 'A tear-shaped, uninhabited tropical coral island surrounded by a shallow lagoon of glowing turquoise and aquamarine waters, enclosed by a living coral reef in the Arabian Sea. Renowned internationally for pristine white-sand shores, phosphorescent plankton glowing at night, sea turtles, stingrays, and world-class scuba diving over untouched coral gardens.', 'beach', 10.9419, 72.2894, 'Flights operate from Kochi to Agatti Island airport, followed by a scenic 45-minute speedboat ride across the open lagoon to Bangaram.', 'Entry permit from the Lakshadweep Administration is mandatory for all visitors, arranged through verified tourism operators or resort bookings. Scuba diving, kayaking, and reef snorkelling operate with certified PADI divemasters. Best visited October to May. Last verified: October 2026.', None, 'https://lakshadweep.gov.in/tourism/', place_image('bangaram-atoll')),
        (72, 25, 'auroville-matrimandir', 'Matrimandir, Auroville', 'An architectural and spiritual icon set in the international township of Auroville near Puducherry. Known as the "Soul of the City", the Matrimandir is a colossal golden geodesic dome surrounded by twelve landscaped petals and gardens, housing a silent white-marble meditation chamber centered around the world’s largest optically worked glass globe reflecting a single beam of sunlight.', 'culture', 11.9338, 79.8322, 'Located 10 km north of Puducherry town center. Easily accessible by taxi, auto-rickshaw, or rented bicycle/scooter along the East Coast Road.', 'Visitor Centre viewing point open Monday to Saturday 9:00 AM to 5:00 PM, Sunday 9:00 AM to 1:00 PM (free entry pass obtained at Visitor Centre). Inner Chamber meditation visits require prior advance booking in person or online. Modest attire requested. Last verified: October 2026.', None, 'https://tourism.py.gov.in/', place_image('auroville-matrimandir')),
        (73, 25, 'promenade-beach-pondicherry', 'Promenade Beach (Rock Beach)', 'Puducherry’s iconic 1.2-kilometre seafront boulevard stretching along the Bay of Bengal from the War Memorial to the Dupleix park. Lined with black volcanic granite boulders, historic colonial heritage landmarks, the 4-metre Mahatma Gandhi statue on four monolithic granite pillars, and the 19th-century Old Light House. The road becomes a joyful pedestrian-only promenade every evening.', 'beach', 11.9333, 79.8358, 'Located along Goubert Avenue in White Town, accessible on foot from anywhere in the French Quarter or 1 km from Puducherry railway station.', 'Open 24 hours. The entire road is closed to motorized vehicles from 6:00 PM to 7:30 AM daily, making it ideal for walking, street music, and sea breezes. Swimming is strictly prohibited due to steep rocky shore drop-offs. Last verified: October 2026.', None, 'https://tourism.py.gov.in/', place_image('promenade-beach-pondicherry')),
        (74, 25, 'aurobindo-ashram', 'Sri Aurobindo Ashram, Puducherry', 'A world-renowned spiritual sanctuary founded in 1926 by Sri Aurobindo and Mirra Alfassa (The Mother). Centered around a tranquil tree-shaded marble courtyard holding the flower-decked Samadhi of Sri Aurobindo and The Mother, the ashram is a haven of contemplative silence, integral yoga study, and library archives in the heart of White Town.', 'spiritual', 11.9366, 79.8344, 'Located on Rue de la Marine in the French Quarter, within a 5-minute walk from Promenade Beach.', 'Open daily 8:00 AM to 12:00 PM and 2:00 PM to 6:00 PM. Free entry. Strict pin-drop silence must be observed inside the Samadhi courtyard. Mobile phones and footwear must be deposited at the entrance counters. Last verified: October 2026.', None, 'https://tourism.py.gov.in/', place_image('aurobindo-ashram')),
        (75, 25, 'white-town-pondicherry', 'White Town (French Heritage Quarter)', 'The historic colonial heart of Puducherry, laid out in an orderly grid of sunlit tree-lined boulevards with authentic French street names (Rue Dumas, Rue Suffren, Rue Romain Rolland). Features mustard-yellow and pastel colonial mansions with high arched gateways, louvered shutters, private courtyards with cascading pink bougainvillea, and chic French-Creole cafes.', 'culture', 11.9317, 79.8333, 'Adjoins Promenade Beach in eastern Puducherry. Best explored on foot, on a rented vintage bicycle, or by cycle-rickshaw.', 'Open all hours. Heritage walking tours operate mornings and late afternoons. Respect private residences when photographing streetscapes. Excellent cafes for croissants, quiches, and French-Tamil fusion cuisine. Last verified: October 2026.', None, 'https://tourism.py.gov.in/', place_image('white-town-pondicherry')),
        (76, 25, 'paradise-beach-pondicherry', 'Paradise Beach & Chunnambar Boat House', 'An isolated, pristine sandspit situated where the Chunnambar River joins the Bay of Bengal, 8 km south of Puducherry. Accessible only via a scenic 15-minute motorboat cruise through dense mangrove-lined backwaters from the Chunnambar Boat House, the beach features soft golden sands, clean waters, and water sports.', 'beach', 11.8842, 79.8164, 'Take an auto-rickshaw or bus along the Cuddalore Road (NH-32) to Chunnambar Boat House (8 km south of town), then board the ferry boat to the beach.', 'Chunnambar Boat House operates daily 9:00 AM to 5:00 PM. Ferry boat tickets: ₹350 per person return. Swimming allowed in designated shallow areas under lifeguard supervision. Beach shacks serve fresh coconut water and snacks. Last verified: October 2026.', None, 'https://tourism.py.gov.in/', place_image('paradise-beach-pondicherry')),
        (77, 25, 'sacred-heart-basilica-pondicherry', 'Basilica of the Sacred Heart of Jesus', 'A rare and breathtaking example of French Gothic-revival architecture in southern India, consecrated in 1907 by French Catholic missionaries. Featuring twin towers, red and white Corinthian columns, soaring rib-vaulted ceilings, and 28 stained-glass windows depicting the life of Jesus and Catholic saints imported from France.', 'heritage', 11.9286, 79.8286, 'Located on South Boulevard near Puducherry Railway Station (a 5-minute walk from the station).', 'Open daily 6:00 AM to 8:00 PM. Free entry. Sunday masses are conducted in Tamil and English. Modest dress required inside the active basilica. The illuminated facade is spectacular during evening hours and Christmas. Last verified: October 2026.', None, 'https://tourism.py.gov.in/', place_image('sacred-heart-basilica-pondicherry')),
        (78, 54, 'ross-island-andaman', 'Ross Island (Netaji Subhash Chandra Bose Dweep)', 'The historic 19th-century British administrative headquarters of the penal settlement, now an evocative ghost town reclaimed by tropical nature. Colossal roots of century-old banyan and peepal trees intertwine around the stone ruins of the Chief Commissioner’s mansion, Presbyterian church, barracks, and ballroom, populated by friendly spotted deer and peacocks.', 'heritage', 11.6739, 92.7631, 'Reached via a 15-minute passenger ferry from Aberdeen Jetty / Rajiv Gandhi Water Sports Complex in Port Blair.', 'Ferry operates 8:30 AM to 3:00 PM (closed Wednesdays). Entry permit: ₹50. Sound and light show in Hindi and English every evening. Electric golf carts available on the island for seniors and families. Last verified: October 2026.', None, 'https://www.andamantourism.gov.in/', place_image('ross-island-andaman')),
        (79, 54, 'elephant-beach-havelock', 'Elephant Beach, Havelock Island', 'One of the premier snorkeling and water sports hubs in the Andaman Islands, situated on the northwestern coast of Swaraj Dweep. Enclosed by shallow turquoise waters, thriving shallow fringing coral reefs alive with clownfish and sea turtles, and white sands framed by dramatic fallen timber trees.', 'beach', 12.0006, 92.9536, 'Accessible via a 20-minute speedboat ride from Havelock jetty or a guided 1.8 km jungle trekking trail through the lush tropical forest.', 'Boats operate 8:00 AM to 2:00 PM. Snorkeling, sea walking, glass-bottom boat tours, and jet-skiing are available with certified guides. Carry reef-safe sunscreen and water shoes. Last verified: October 2026.', None, 'https://www.andamantourism.gov.in/', place_image('elephant-beach-havelock')),
        (80, 55, 'baratang-island-caves', 'Baratang Island Limestone Caves & Mangroves', 'A dramatic adventure in Middle Andaman, reached by speedboat through dense saltwater mangrove canopies that form a natural cathedral over the creeks. A scenic trek through tropical rainforest leads to monumental limestone karst caves featuring millennia-old stalactites and stalagmites hanging like crystal chandeliers.', 'nature', 12.1167, 92.7500, 'Located 100 km north of Port Blair. Accessible by vehicle convoy along the Andaman Trunk Road (NH-4) passing through the Jarawa tribal reserve, followed by a short Nilambur jetty ferry and mangrove boat ride.', 'Vehicle convoy timings from Jirkatang check-post are strictly fixed (6:00 AM and 9:00 AM). Photography is strictly prohibited along the tribal reserve corridor. Carry torches/flashlights to explore the cave interiors. Last verified: October 2026.', None, 'https://www.andamantourism.gov.in/', place_image('baratang-island-caves')),
        (81, 26, 'sukhna-lake', 'Sukhna Lake & Shivalik Promenade', 'A picturesque 3-square-kilometer rain-fed reservoir created in 1958 at the foothills of the Shivaliks, conceived by Le Corbusier as an uncommercialized sanctuary for quiet contemplation. Features a scenic 2-mile walking promenade, swan paddleboats and shikaras, open-air cafes, and a winter haven for Siberian migratory ducks and cranes.', 'nature', 30.7422, 76.8183, 'Located in Sector 1, accessible by taxi, auto-rickshaw, or city bus, 5 km from Chandigarh railway station.', 'Open 24 hours daily; boating operates 9:30 AM to 6:00 PM. Boating tickets: ₹100–₹400 depending on boat type. Motorized watercraft are strictly prohibited to preserve water quality and birdlife. Sunrise and sunset are the most popular hours. Last verified: October 2026.', None, 'https://chandigarhtourism.gov.in/', place_image('sukhna-lake')),
        (82, 26, 'rose-garden-chandigarh', 'Zakir Hussain Rose Garden, Chandigarh', 'Asia’s largest rose garden, spanning 30 landscaped acres in Sector 16. Named after India\'s former president Dr. Zakir Hussain, the garden showcases over 50,000 rose bushes across 825 distinct varieties, alongside carved lawns, fountains, and trees of medicinal importance. The annual three-day Rose Festival in February is the city’s premier cultural fair.', 'nature', 30.7472, 76.7844, 'Located in Sector 16 along Jan Marg, easily reached from Sector 17 city center on foot or by auto-rickshaw.', 'Open daily 6:00 AM to 8:00 PM. Free entry. Peak blooming season is from December to March. The garden has paved walking paths and illuminated fountains in the evening. Last verified: October 2026.', None, 'https://chandigarhtourism.gov.in/', place_image('rose-garden-chandigarh')),
        (83, 26, 'capitol-complex-open-hand', 'Le Corbusier Capitol Complex & Open Hand', 'The monumental administrative core of Chandigarh, inscribed as a UNESCO World Heritage Site in 2016. Spanning 100 acres against the Shivalik hills, the complex showcases Le Corbusier\'s architectural masterpieces: the High Court, the Secretariat, the Legislative Assembly, and the iconic 26-metre-tall rotating Open Hand Monument, symbolizing peace and reconciliation.', 'heritage', 30.7583, 76.8042, 'Located in Sector 1, northern end of Jan Marg. Guided tours depart from the Tourist Facilitation Center in Sector 1.', 'UNESCO World Heritage component site. Guided walking tours operate three times daily (10:00 AM, 12:00 PM, 3:00 PM). Prior registration with valid photo ID at the Tourist Facilitation Center is required for security clearance. Last verified: October 2026.', 13, 'https://whc.unesco.org/en/list/1321/', place_image('capitol-complex-open-hand')),
        (84, 57, 'naida-caves-diu', 'Naida Caves, Diu Island', 'A labyrinthine geological wonderland of natural sunlit limestone caverns and carved rock passages located just outside the city walls of Diu Fort. Formed by natural ocean erosion and expanded by centuries of Portuguese quarrying for building fortresses, the caves feature dramatic rock pillars, hanging ficus roots, and shafts of sunlight illuminating the caverns.', 'nature', 20.7100, 70.9767, 'Located on Delwada Road near the southern ramparts of Diu town, easily accessible by auto-rickshaw, rented scooter, or taxi.', 'Open daily 6:30 AM to 6:30 PM. Free entry. Wear comfortable footwear with good grip on stone surfaces. Midday hours offer the most dramatic light rays penetrating the cave openings for photography. Last verified: October 2026.', None, 'https://dnhddtourism.in/', place_image('naida-caves-diu')),
        (85, 57, 'nagoa-beach-diu', 'Nagoa Beach & Hoka Palm Coast', 'A crescent horseshoe-shaped bay renowned for its calm, crystal-clear swimming waters and soft white sands, located 7 km from Diu town. The beach is unique in India for its dense groves of rare branching Hoka trees (African doum palms, Hyphaene thebaica), brought by Portuguese sailors from East Africa centuries ago.', 'beach', 20.7042, 70.9167, 'Located 7 km west of Diu town center and 2 km from Diu Airport. Readily connected by auto-rickshaws, shared minibuses, and rental two-wheelers.', 'Open sunrise to sunset. Safe for swimming due to sheltered bay waters; lifeguards on duty. Water sports including parasailing, banana rides, and jet-skiing are available. Beachfront resorts and seafood dhabas line the entrance. Last verified: October 2026.', None, 'https://dnhddtourism.in/', place_image('nagoa-beach-diu')),
        (86, 58, 'jampore-beach-daman', 'Jampore Beach, Daman', 'A wide, peaceful beach situated in South Daman along the Arabian Sea, known for its firm dark-tinted sands and shallow, placid waters that allow visitors to walk far into the sea at low tide. Fringed by shady casuarina groves, it is Daman’s most relaxed coastal leisure destination, complete with beach shacks and parasailing.', 'beach', 20.3792, 72.8250, 'Located 5 km south of Moti Daman fort. Easily accessible by taxi, auto-rickshaw, or private vehicle along the coastal road.', 'Open 24 hours daily. Safe for wading and swimming at high tide. Water sports and camel rides operate during daytime. Beach shacks serve fresh fried prawns, fish cutlets, and chilled beverages. Last verified: October 2026.', None, 'https://dnhddtourism.in/', place_image('jampore-beach-daman')),
        (87, 63, 'akshardham-temple-delhi', 'Swaminarayan Akshardham, Delhi', 'A monumental modern Hindu temple complex inaugurated in 2005 on the banks of the Yamuna River. Built according to ancient Vastu Shastra principles from Rajasthani pink sandstone and Italian Carrara marble without steel or concrete support, it features 234 intricately carved pillars, 148 life-sized stone elephants, the Sahaj Anand water laser fountain show, and an indoor cultural boat ride.', 'spiritual', 28.6127, 77.2773, 'Located on NH-24 in East Delhi. Direct access via Akshardham Metro Station on the Blue Line, with a dedicated pedestrian entry.', 'Open Tuesday to Sunday 9:30 AM to 8:00 PM (closed Mondays). Temple entry is free; exhibition and musical fountain tickets: ₹250 for adults. Electronic items, bags, mobile phones, and cameras are strictly prohibited inside the complex (free secure cloakroom available). Last verified: October 2026.', None, 'https://delhitourism.gov.in/', place_image('akshardham-temple-delhi')),
        (88, 62, 'lotus-temple-delhi', 'Lotus Temple (Bahá’í House of Worship)', 'An architectural wonder designed by Iranian-Canadian architect Fariborz Sahba in the shape of a blooming white lotus flower, open to people of all religious faiths. Completed in 1986, the structure features 27 free-standing marble petals arranged in clusters of three to form nine doors opening onto a central hall capable of holding 2,500 people, surrounded by nine serene blue ponds.', 'spiritual', 28.5535, 77.2588, 'Located in Kalkaji, South Delhi. Accessible via Kalkaji Mandir Metro Station (Violet and Magenta lines), a 5-minute walk away.', 'Open Tuesday to Sunday 9:00 AM to 5:30 PM (closed Mondays). Free entry. Absolute silence is maintained inside the central prayer hall; no religious sermons or musical instruments are permitted. Footwear must be deposited in designated bags at the gate. Last verified: October 2026.', None, 'https://delhitourism.gov.in/', place_image('lotus-temple-delhi')),
        (89, 60, 'jama-masjid-delhi', 'Jama Masjid, Old Delhi', 'India’s largest historic congregational mosque, commissioned by Mughal Emperor Shah Jahan in 1650 and completed in 1656 by 5,000 artisans. Built of red sandstone and white marble with three grand domes, two 40-metre-high minarets, and an expansive courtyard holding 25,000 worshippers, overlooking the vibrant historic lanes of Chandni Chowk.', 'heritage', 28.6507, 77.2334, 'Located in Old Delhi, 500 m west of the Red Fort. Direct access via Jama Masjid Metro Station on the Heritage (Violet) Line.', 'Open daily 7:00 AM to 12:00 PM and 1:30 PM to 6:30 PM (tourists not permitted during prayer times). Free entry; nominal camera fee of ₹300. Modest dress covering shoulders and legs required (robes provided at gate). Climbing the southern minaret offers panoramic views over Old Delhi. Last verified: October 2026.', None, 'https://delhitourism.gov.in/', place_image('jama-masjid-delhi')),
        (90, 21, 'bangla-sahib-delhi', 'Gurudwara Bangla Sahib, New Delhi', 'One of the most prominent historic Sikh shrines in India, originally the 17th-century bungalow (haveli) of Raja Jai Singh of Amber, associated with the eighth Sikh Guru, Guru Har Krishan. Renowned for its dazzling golden dome, serene sacred water pool (Sarovar) believed to have healing properties, and a 24/7 community mega-kitchen (Langar) that serves free wholesome hot meals to over 30,000 visitors every day regardless of religion or background.', 'spiritual', 28.6263, 77.2090, 'Located on Ashoka Road near Connaught Place. Accessible via Patel Chowk or Shivaji Stadium metro stations (a 5-minute walk).', 'Open 24 hours daily. Free entry and free community dining (Langar). Head coverings and modest attire are mandatory for all visitors (scarves provided free at entrance). Footwear must be deposited at the shoe counter. Last verified: October 2026.', None, 'https://delhitourism.gov.in/', place_image('bangla-sahib-delhi')),
        (91, 71, 'pahalgam-betaab-valley', 'Pahalgam & Betaab Valley, Lidder River', 'The world-famous "Valley of the Shepherds" at 2,130 m along the crystalline glacial Lidder River in South Kashmir. Named after the hit Bollywood movie Betaab shot there, the valley is framed by dense deodar and pine forests, rushing mountain torrents, horse riding trails to Baisaran ("Mini Switzerland"), and serves as the primary base for the sacred annual Amarnath Cave Yatra.', 'nature', 34.0150, 75.3150, 'Located 95 km southeast of Srinagar (approx. 2.5-hour drive via Anantnag and the apple valley highway). Accessible by private taxi or shared cab.', 'Open year-round; summer offers pleasant green meadows, winter brings thick snow. Local pony rides and union taxis operate for sightseeing to Aru Valley, Betaab Valley, and Chandanwari. Trout fishing permits can be obtained from the Fisheries Department. Last verified: October 2026.', None, 'https://jammutourism.jk.gov.in/', place_image('pahalgam-betaab-valley')),
        (92, 22, 'shankaracharya-temple', 'Shankaracharya Temple, Srinagar', 'An ancient stone temple perched atop the forested Shankaracharya Hill (Takht-e-Suleiman) at an elevation of 1,100 feet above the valley floor. Dedicated to Lord Shiva and associated with the visit of the philosopher Adi Shankara in the 8th century, the octagonal stone sanctum commands magnificent 360-degree panoramic views of Srinagar city, Dal Lake, and the Pir Panjal mountains.', 'spiritual', 34.0858, 74.8475, 'Located in southeast Srinagar. Reached by road up to the base parking, followed by a climb of 243 stone steps to the summit shrine.', 'Open daily 6:00 AM to 8:00 PM. High-security checkpoint at entrance; cameras, mobile phones, and electronic devices are strictly prohibited and must be left in vehicles. Wear comfortable walking shoes for the 243 stone steps. Breathtaking morning vistas of Dal Lake. Last verified: October 2026.', None, 'https://jammutourism.jk.gov.in/', place_image('shankaracharya-temple')),
        (93, 72, 'sonamarg-thajiwas', 'Sonamarg & Thajiwas Glacier', 'Known as the "Meadow of Gold" at 2,740 m along the roaring Sindh River in Ganderbal district. Flanked by towering glaciated peaks, it is the starting point for high-altitude treks to the Great Lakes and the northern route to Ladakh via Zoji La pass. A scenic 3 km pony ride or hike leads to the glistening ice fields and cascading waterfalls of the Thajiwas Glacier.', 'nature', 34.3100, 75.2933, 'Located 80 km northeast of Srinagar along the Srinagar-Leh Highway (NH-1D, approx. 2.5-hour drive). Accessible by private taxi or bus.', 'Open seasonally from April to November (closed in deep winter by heavy snow). Pony rentals and local sledge operators are available at fixed rates. Excellent base for river rafting on the Sindh River and high alpine walks. Last verified: October 2026.', None, 'https://jammutourism.jk.gov.in/', place_image('sonamarg-thajiwas')),
        (94, 22, 'nishat-shalimar-gardens', 'Shalimar & Nishat Mughal Gardens', 'The twin crowns of Mughal garden architecture on the eastern shores of Dal Lake, created in 1619 by Emperor Jahangir (Shalimar Bagh, "Abode of Love") and in 1633 by Asif Khan (Nishat Bagh, "Garden of Bliss"). Designed as terraced Persian Charbaghs, they feature stone water channels, cascading fountains, marble pavilions, and avenues of majestic Chinar trees overlooking the lake.', 'heritage', 34.1350, 74.8722, 'Located along Boulevard / Foreshore Road in northeast Srinagar, 12 km from city center. Readily accessible by taxi, auto-rickshaw, or shikara boat.', 'UNESCO Tentative List site. Open daily 9:00 AM to 7:00 PM. Nominal entry fee (₹24 per person). Peak beauty in spring (April–May) with blooming flowers and autumn (October–November) when Chinar leaves turn glowing amber and crimson. Last verified: October 2026.', 12, 'https://whc.unesco.org/en/tentativelists/5574/', place_image('nishat-shalimar-gardens')),
        (95, 24, 'leh-palace-shanti-stupa', 'Leh Palace & Shanti Stupa', 'The twin architectural emblems of Leh town. Leh Palace is a dramatic nine-story stone and timber royal citadel built in 1600 by King Sengge Namgyal, offering rooftop panoramas of the mud-brick old town and Ladakh Range. Nearby atop the Changspa hill stands Shanti Stupa, a radiant white-domed Buddhist peace pagoda built by Japanese and Ladakhi monks, famed for golden sunset vistas of Stok Kangri (6,153 m).', 'heritage', 34.1658, 77.5858, 'Located in central Leh. Leh Palace is reached via a 15-minute walk from the Old Market; Shanti Stupa is accessible by taxi or a 500-step stair climb from Changspa.', 'Leh Palace open daily 7:00 AM to 6:00 PM (ASI ticketed: ₹25 Indians, ₹300 foreigners). Shanti Stupa open 5:00 AM to 9:00 PM (free entry). The sunset from Shanti Stupa when the Indus valley glows purple and gold is an unforgettable Himalayan spectacle. Last verified: October 2026.', None, 'https://ladakh.gov.in/tourism/', place_image('leh-palace-shanti-stupa')),
        (96, 24, 'sangam-indus-zanskar', 'Sangam (Indus & Zanskar Confluence) & Magnetic Hill', 'The spectacular confluence point at Nimmu (30 km west of Leh) where the jade-green, tranquil waters of the Indus River merge with the rapid, muddy-brown torrents of the Zanskar River. Along the same highway lies Magnetic Hill—a famous gravity-defying optical illusion where vehicles in neutral gear appear to roll uphill—and the historic 16th-century Gurudwara Pathar Sahib built to commemorate Guru Nanak’s visit.', 'nature', 34.1650, 77.3325, 'Located 30 to 35 km west of Leh along the Leh-Srinagar Highway (NH-1). Readily visited as a half-day trip from Leh by taxi or rental motorcycle.', 'Open all hours. The color contrast between the two rivers is sharpest between May and October. Sangam is also the premier launching point for white-water river rafting (Grade III/IV) through the deep Zanskar gorge. Last verified: October 2026.', None, 'https://ladakh.gov.in/tourism/', place_image('sangam-indus-zanskar')),
        (97, 24, 'khardung-la-pass', 'Khardung La Pass (5,359 m)', 'A legendary mountain pass on the Ladakh Range at an altitude of 5,359 metres (17,582 ft), celebrated globally as one of the highest motorable roads on Earth. Serving as the historic caravan gateway from the Indus Valley into the Nubra Valley and on to the ancient Silk Route, the summit provides sweeping vistas of the snow-clad Karakoram Range.', 'nature', 34.2789, 77.6044, 'Located 39 km north of Leh along the road to Nubra. Reachable by private 4x4 taxi, high-clearance SUV, or rented adventure motorcycle.', 'Inner Line Permit (ILP) required. Due to extremely thin air and low oxygen levels, visitors are strongly advised not to stay at the summit for more than 15–20 minutes. The Army medical center and cafe operate at the pass. Heavy snow can occur unexpectedly even in summer. Last verified: October 2026.', None, 'https://ladakh.gov.in/tourism/', place_image('khardung-la-pass')),
        (98, 24, 'hemis-monastery', 'Hemis Monastery (Changchubling)', 'The largest, richest and most revered Buddhist monastery in Ladakh, belonging to the Drukpa Kagyu lineage. Hidden inside a dramatic gorge 45 km south of Leh, the 17th-century complex contains a sacred golden stupa encrusted with turquoise and pearls, historic thangkas (including the world’s largest silk thangka unfurled once every 12 years), an extensive museum of Buddhist relics, and the venue of the world-famous annual Hemis Tsechu festival.', 'spiritual', 33.9125, 77.7081, 'Located 45 km southeast of Leh along the Indus River valley. Easily accessible by private taxi or local bus via Karu.', 'Open daily 8:00 AM to 6:00 PM. Museum entry fee: ₹50. The monastery courtyard hosts the vibrant 2-day Hemis Festival in June/July featuring sacred Cham masked dances and traditional long-horn trumpets. Last verified: October 2026.', None, 'https://ladakh.gov.in/tourism/', place_image('hemis-monastery')),
        (99, 91, 'agatti-island-lagoon', 'Agatti Island Lagoon & Coral Atoll', 'The primary aviation gateway to Lakshadweep, featuring a 6-km-long coral island with an airstrip extending directly between translucent turquoise lagoons. Renowned for multi-colored coral reefs, shallow calm waters ideal for glass-bottom boat rides, snorkeling with sea turtles, and kayaking in calm inland lagoons.', 'beach', 10.8533, 72.1931, 'Direct daily flights operate from Kochi to Agatti Airport (AGX). Speedboats transfer passengers to other islands like Bangaram and Kadmat from the Agatti jetty.', 'Entry permit from the Lakshadweep Administration is mandatory. Water sports centers provide certified snorkeling gear, scuba diving, and deep-sea fishing charters. Best visited from October to May. Last verified: October 2026.', None, 'https://lakshadweep.gov.in/tourism/', place_image('agatti-island-lagoon')),
        (100, 91, 'kavaratti-island', 'Kavaratti Island & Marine Aquarium', 'The administrative capital of Lakshadweep, famous for its calm lagoons, swaying coconut groves, and rich Islamic heritage with 52 mosques. Features the exquisite 17th-century Ujra Mosque with ceiling carvings from single blocks of driftwood, the Kavaratti Marine Aquarium showcasing endangered live corals, sea anemones, and sharks, and water sports at the Dolphin Dive Center.', 'beach', 10.5667, 72.6333, 'Reached via passenger ship or inter-island helicopter/ferry service from Agatti Island.', 'Permit required. Marine Aquarium open daily 9:00 AM to 5:00 PM. Scuba diving, windsurfing, and glass-bottom boating operate at the lagoon. Last verified: October 2026.', None, 'https://lakshadweep.gov.in/tourism/', place_image('kavaratti-island')),
        (101, 91, 'kadmat-island-diving', 'Kadmat Island & Scuba Diving Reef', 'A slender, teardrop coral island stretching 8 km in length but only 550 m wide, bordered on both east and west by immense shallow lagoons of dazzling turquoise water. Blessed with a massive living coral reef ecosystem, Kadmat is home to India’s premier government-operated water sports and PADI scuba diving center, offering sightings of manta rays, moray eels, and green sea turtles.', 'nature', 11.2333, 72.7833, 'Accessible via speedboat or passenger ferry from Agatti Island (approx. 2.5-hour sea journey across the open lagoon).', 'Entry permit required. The resort operates dive courses and excursions from October to May. Alcohol is strictly prohibited on the island. Pristine beaches with very low tourist density. Last verified: October 2026.', None, 'https://lakshadweep.gov.in/tourism/', place_image('kadmat-island-diving')),
        (102, 26, 'leisure-valley-chandigarh', 'Leisure Valley & Linear Park', 'The emerald lung of Chandigarh, conceived by Le Corbusier as an unbroken 8-kilometre linear green corridor extending from Sector 1 in the north down to the southern sectors along a natural seasonal stream valley. Features walking trails, cycling tracks, indigenous flora, and connects the city\'s premier gardens.', 'nature', 30.75289, 76.79234, 'Stretches across Sectors 1, 3, 10, 16, 23, 36 and 42. Easily accessible from multiple sector entrance points.', 'Open 24 hours daily. Free entry. Popular for morning yoga, walking, and jogging. Beautiful during blooming seasons. Last verified: October 2026.', None, 'https://chandigarhtourism.gov.in/', place_image('leisure-valley-chandigarh')),
        (103, 26, 'garden-of-fragrance', 'Garden of Fragrance', 'A specialized botanical fragrance haven in Sector 36, celebrated for its aromatic flowering plants, shrubs, and fragrant trees. Planted with damask roses, night-blooming jasmine (raat ki rani), motia, champa, haar-shringar, and mehendi, filling the evening air with natural perfume.', 'nature', 30.73267, 76.75721, 'Located in Sector 36-B, accessible via Dakshin Marg and Himalaya Marg.', 'Open daily 5:00 AM to 8:00 PM. Free entry. Early morning and twilight are the best hours to experience the full floral fragrance. Last verified: October 2026.', None, 'https://chandigarhtourism.gov.in/', place_image('garden-of-fragrance')),
        (104, 26, 'hibiscus-garden', 'Hibiscus Garden', 'A 8-acre botanical park in Sector 36 dedicated entirely to the hibiscus family, showcasing over 40 distinct varieties of colorful hybrid hibiscus shrubs that bloom throughout the year alongside towering date palms and weeping willows.', 'nature', 30.73564, 76.75925, 'Located in Sector 36-A, adjacent to the post office and Dakshin Marg.', 'Open daily 6:00 AM to 8:00 PM. Free entry. Quiet paved walking trails, manicured grass lawns, and wooden benches. Last verified: October 2026.', None, 'https://chandigarhtourism.gov.in/', place_image('hibiscus-garden')),
        (105, 26, 'garden-of-palms', 'Garden of Palms', 'A scenic 19.5-acre thematic park in Sector 42 dedicated to the palm family, featuring over 21 species of exotic and indigenous palm trees, meandering cycling tracks, wooden bridges across water bodies, a solar-illuminated plaza, and an adventure play area.', 'nature', 30.72561, 76.73706, 'Located in Sector 42 near the lake, accessible via Shanti Path.', 'Open daily 6:00 AM to 8:00 PM. Free entry. Has extensive parking and dedicated cycling paths. Last verified: October 2026.', None, 'https://chandigarhtourism.gov.in/', place_image('garden-of-palms')),
        (106, 26, 'topiary-park', 'Topiary Park', 'An imaginative landscape park in Sector 35 created in 1987, featuring ornamental bushes and creepers meticulously sculpted into whimsical shapes of animals including elephants, bears, deer, and geometric arches for children and families.', 'nature', 30.72686, 76.76125, 'Located in Sector 35-A, accessible via Jan Marg.', 'Open daily 6:00 AM to 8:00 PM. Free entry. Features open play areas and ornamental shrubs. Last verified: October 2026.', None, 'https://chandigarhtourism.gov.in/', place_image('topiary-park')),
        (107, 26, 'terrace-garden-chandigarh', 'Terraced Garden & Musical Fountain', 'A beloved 10-acre multi-tiered terraced garden in Sector 33 established in 1979. Famed for its colorful floral terraces, seasonal chrysanthemum shows, and an illuminated evening musical fountain that dances to Indian classical and folk melodies.', 'nature', 30.71442, 76.77164, 'Located in Sector 33-B, near Shanti Path and Subhash Chander Bose Marg.', 'Open daily 5:30 AM to 9:00 PM. Free entry. The musical fountain operates in the evening (7:00 PM to 8:30 PM). The annual Chrysanthemum Show in December is a major event. Last verified: October 2026.', None, 'https://chandigarhtourism.gov.in/', place_image('terrace-garden-chandigarh')),
        (108, 26, 'shanti-kunj', 'Shanti Kunj Garden', 'A peaceful noise-free garden sanctuary situated in Sector 16 between the Rose Garden and Cricket Stadium. Divided into five tranquil zones by a natural stream, planted with medicinal herbs, weeping willows, and flowering trees offering quiet shade.', 'nature', 30.7490, 76.7865, 'Located in Sector 16, within walking distance from Zakir Hussain Rose Garden.', 'Open daily 5:00 AM to 8:00 PM. Free entry. Strictly maintained as a quiet contemplation zone. Last verified: October 2026.', None, 'https://chandigarhtourism.gov.in/', place_image('shanti-kunj')),
        (109, 26, 'bougainvillea-garden', 'Bougainvillea Garden', 'A sprawling 20-acre garden established in 1976 in Sector 3, showcasing over 65 vibrant varieties of bougainvillea trained over arches, pavilions, and bowers, interspersed with flowering gulmohar, jacaranda, and amaltas trees.', 'nature', 30.7580, 76.7910, 'Located in Sector 3 along Uttar Marg, near the War Memorial.', 'Open daily 6:00 AM to 8:00 PM. Free entry. Peak blooming occurs in spring and autumn when the arches are smothered in magenta, crimson, white, and orange flowers. Last verified: October 2026.', None, 'https://chandigarhtourism.gov.in/', place_image('bougainvillea-garden')),
        (110, 26, 'war-memorial-chandigarh', 'Chandigarh War Memorial', 'The largest post-independence war memorial in India, inaugurated in 2006 by former President Dr. A.P.J. Abdul Kalam. Located inside Bougainvillea Garden, the circular pink sandstone monument is inscribed with the names of over 8,450 martyrs of the Indian Army, Navy, and Air Force since 1947.', 'heritage', 30.7585, 76.7905, 'Located within Bougainvillea Garden in Sector 3, accessible via Uttar Marg.', 'Open daily 6:00 AM to 8:00 PM. Free entry. Solemn national monument with eternal flame and ceremonial wreaths. Last verified: October 2026.', None, 'https://chandigarhtourism.gov.in/', place_image('war-memorial-chandigarh')),
        (111, 26, 'sector-17-plaza', 'Sector 17 City Centre & Plaza', 'The bustling pedestrian heart of Chandigarh, planned as the city’s civic and commercial center. Free of motorized vehicles, the plaza features broad paved avenues, modernist concrete colonnades, open-air amphitheaters, an illuminated musical fountain, brand boutiques, and traditional street cafes.', 'culture', 30.74105, 76.77902, 'Located in Sector 17, easily reachable by cab, auto-rickshaw, or city bus from anywhere in the city.', 'Open daily 10:30 AM to 9:30 PM. Pedestrian-only zone. Famous for street performers, musical fountain shows in the evening, and North Indian food. Last verified: October 2026.', None, 'https://chandigarhtourism.gov.in/', place_image('sector-17-plaza')),
        (112, 26, 'government-museum-art-gallery', 'Government Museum and Art Gallery', 'Designed by Le Corbusier and opened in 1968, this premier museum houses one of India’s finest collections of ancient Gandharan stone sculptures, Pahari and Mughal miniature paintings, medieval Indian bronzes, and modern Indian art.', 'heritage', 30.7486, 76.7905, 'Located in Sector 10-C, near the Rose Garden and Matka Chowk.', 'Open Tuesday to Sunday 10:00 AM to 4:30 PM (closed Mondays and official holidays). Ticket: ₹30 per adult. Guided tours and museum reference library available. Last verified: October 2026.', None, 'https://chandigarhtourism.gov.in/', place_image('government-museum-art-gallery')),
        (113, 26, 'natural-history-museum-chandigarh', 'Natural History Museum, Chandigarh', 'A fascinating evolutionary science museum in Sector 10 featuring life-sized dinosaur models, fossilized remains from the Shivalik hills, geological displays, the story of human origin, and exhibitions on prehistoric life and human evolution.', 'heritage', 30.7480, 76.7915, 'Located in the Cultural Complex of Sector 10, adjacent to the Government Museum and Art Gallery.', 'Open Tuesday to Sunday 10:00 AM to 4:30 PM (closed Mondays). Ticket: ₹30 per adult. Excellent for families, students, and natural history enthusiasts. Last verified: October 2026.', None, 'https://chandigarhtourism.gov.in/', place_image('natural-history-museum-chandigarh')),
        (114, 26, 'chandigarh-architecture-museum', 'Chandigarh Architecture Museum', 'Housed in a Corbusian modular concrete building in Sector 10, this museum documents the unique founding and planning of Chandigarh through rare original sketches, blueprints, letters between Nehru and Le Corbusier, vintage photographs, and architectural models.', 'heritage', 30.7495, 76.7900, 'Located in the Sector 10 Cultural Complex, within walking distance of the Art Gallery.', 'Open Tuesday to Sunday 10:00 AM to 4:30 PM (closed Mondays). Ticket: ₹10 per person. An indispensable visit for architecture and modern heritage lovers. Last verified: October 2026.', None, 'https://chandigarhtourism.gov.in/', place_image('chandigarh-architecture-museum')),
        (115, 26, 'iaf-heritage-centre-chandigarh', 'Indian Air Force Heritage Centre', 'Inaugurated in 2023 in Sector 18, this state-of-the-art military aviation museum honors the valour and technological history of the Indian Air Force. Displays decommissioned fighter aircraft including the MiG-21, surface-to-air missile systems, flight simulators, and war memorial exhibits.', 'heritage', 30.73919, 76.79096, 'Located in the Government Press Building, Sector 18 along Madhya Marg.', 'Open Tuesday to Sunday 10:00 AM to 6:00 PM (closed Mondays). Entry ticket: ₹50. Cockpit flight simulators available with advance booking at the counter. Last verified: October 2026.', None, 'https://chandigarhtourism.gov.in/', place_image('iaf-heritage-centre-chandigarh')),
        (116, 26, 'le-corbusier-centre-chandigarh', 'Le Corbusier Centre', 'The historic Sector 19 heritage building that served as Le Corbusier’s active architecture and town-planning studio during the creation of Chandigarh. Now a museum preserving his drafting tables, personal notes, original sketches, correspondence, and modernist furniture designed with Pierre Jeanneret.', 'heritage', 30.72982, 76.79954, 'Located in Sector 19-B along Old Architect Building road.', 'Open Tuesday to Sunday 10:00 AM to 5:00 PM (closed Mondays). Entry ticket: ₹20. Essential pilgrimage site for modernist architecture admirers. Last verified: October 2026.', None, 'https://chandigarhtourism.gov.in/', place_image('le-corbusier-centre-chandigarh')),
        (117, 26, 'maison-jeanneret', 'Pierre Jeanneret Museum (Maison Jeanneret)', 'The lovingly restored modernist residence of Swiss architect Pierre Jeanneret (Le Corbusier’s cousin and Chief Architect of Chandigarh), where he lived from 1954 to 1965. Showcases authentic mid-century Chandigarh furniture, teak and cane chairs, working drawings, and personal memorabilia.', 'heritage', 30.7510, 76.8010, 'Located at House No. 57, Sector 5, near the Sukhna Lake green belt.', 'Open Tuesday to Sunday 10:00 AM to 5:00 PM (closed Mondays). Entry ticket: ₹10. Offers intimate glimpses into mid-century design and domestic living in early Chandigarh. Last verified: October 2026.', None, 'https://chandigarhtourism.gov.in/', place_image('maison-jeanneret')),
        (118, 26, 'garden-of-silence', 'Garden of Silence', 'A serene meditative park situated at the tranquil eastern terminus of Sukhna Lake. Features a majestic seated white marble statue of Gautama Buddha surrounded by circular concentric stone terraces, paved meditation walkways, and lush deodars against the Shivalik hills.', 'spiritual', 30.7380, 76.8280, 'Located at the Regulator end (eastern bank) of Sukhna Lake, accessible via Kishangarh Road or the lake promenade.', 'Open daily 6:00 AM to 8:00 PM. Free entry. A favorite retreat for silent morning meditation, yoga, and reflective sunset contemplation away from city bustle. Last verified: October 2026.', None, 'https://chandigarhtourism.gov.in/', place_image('garden-of-silence')),
        (119, 26, 'japanese-garden-chandigarh', 'Japanese Garden, Chandigarh', 'A beautifully designed 13-acre themed park in Sector 31 inaugurated in 2014, reflecting Japanese Zen aesthetics. Features pagoda towers, traditional red Torii gates, cascading waterfalls, Zen meditation rocks, a golden Buddha statue, and underground pedestrian tunnel galleries with Japanese murals.', 'nature', 30.7040, 76.7760, 'Located in Sector 31 along Dakshin Marg, easily reachable from Chandigarh airport or railway station.', 'Open daily 5:00 AM to 10:00 PM. Free entry. The park is illuminated with Japanese lanterns in the evening and features arched bridges across water bodies. Last verified: October 2026.', None, 'https://chandigarhtourism.gov.in/', place_image('japanese-garden-chandigarh')),
        (120, 26, 'butterfly-park-chandigarh', 'Butterfly Park, Chandigarh', 'A 7-acre dedicated ecological sanctuary in Sector 26 created to conserve and nurture native butterfly species. Planted with host and nectar plants like marigolds, citrus, and lantana, the park hosts over 35 species of colorful butterflies including swallowtails, monarchs, and blue pansies.', 'nature', 30.7310, 76.8080, 'Located in Sector 26 opposite the Chandigarh College of Engineering and Technology.', 'Open daily 9:00 AM to 5:00 PM. Free entry. Best visited during sunny morning hours from March to May and September to November when butterflies are most active. Last verified: October 2026.', None, 'https://chandigarhtourism.gov.in/', place_image('butterfly-park-chandigarh')),
        (121, 28, 'dhauli-shanti-stupa', 'Dhauli Shanti Stupa & Ashokan Edicts', 'The historic site on the banks of the Daya River linked to the Kalinga War (261 BCE), where Emperor Ashoka renounced conquest and embraced Buddhism and non-violence. Crowning the hill is the radiant white Peace Pagoda (Vishwa Shanti Stupa) built in 1972 by Kalinga Nippon Buddha Sangha, alongside 3rd-century BCE Ashokan rock edicts and an ancient rock-cut elephant.', 'spiritual', 20.1925, 85.8394, 'Located 8 km south of Bhubaneswar on the Puri highway. Easily reached by auto-rickshaw, cab, or Mo Bus from the capital.', 'Open daily 6:00 AM to 6:00 PM. No entry fee. Evening sound and light show operates Tuesday to Sunday (₹25 per person). Wheelchair ramps and paved pathways lead to the stupa. Last verified: October 2026.', 15, 'https://odishatourism.gov.in/en/w/dhauli-shanti-stupa-dhauli-hills', place_image('dhauli-shanti-stupa')),
        (122, 28, 'udayagiri-khandagiri-caves', 'Udayagiri & Khandagiri Caves', 'A monumental complex of 33 rock-cut caves carved into two adjacent sandstone hills in the 2nd century BCE during the reign of King Kharavela of the Chedi dynasty. Served as residential cells and sanctuaries for Jain ascetics, featuring the famous 17-line Brahmi Hathigumpha inscription, the two-story Rani Gumpha with sculptural friezes, and carvings of royal processions.', 'heritage', 20.2589, 85.7867, 'Located 6 km west of Bhubaneswar city center. Well connected by city buses, cabs, and auto-rickshaws along the Baramunda corridor.', 'Open daily sunrise to sunset. Ticketed entry via ASI online portal: ₹25 for Indian nationals, ₹300 for foreign visitors. Khandagiri hill is free. Wear walking shoes with grip for climbing rock-cut stairs. Monkeys are present—keep bags zipped. Last verified: October 2026.', None, 'https://odishatourism.gov.in/en/w/udayagiri-khandagiri-caves', place_image('udayagiri-khandagiri-caves')),
        (123, 28, 'mukteswara-temple', 'Mukteswara Temple (Gem of Odisha Architecture)', 'A 10th-century architectural masterpiece hailed as the "Gem of Odishan Temple Architecture", marking the transition between the early and later Kalinga styles. Renowned for its exquisite free-standing stone torana (arched gateway) influenced by Buddhist architecture, intricately carved with reclining maidens, floral scrolls, and the sacred Marichi water tank.', 'heritage', 20.2428, 85.8361, 'Located in Old Town, Bhubaneswar, 5 km from Bhubaneswar Railway Station. Easily accessible by auto-rickshaw or taxi.', 'Open daily 6:30 AM to 7:00 PM. No entry fee. Footwear must be removed at the courtyard gate. The annual Mukteswar Dance Festival in January showcases classical Odissi dance against the illuminated stone temple backdrop. Last verified: October 2026.', None, 'https://odishatourism.gov.in/en/w/mukteswara-temple', place_image('mukteswara-temple')),
        (124, 28, 'rajarani-temple', 'Rajarani Temple (The Love Temple)', 'An 11th-century temple built of warm, golden-yellow sandstone locally called Rajarani stone. Unique in Bhubaneswar for having no presiding deity in the sanctum, the temple is celebrated internationally for its sculptural brilliance—featuring exquisite high-relief carvings of nayikas (graceful maidens), celestial dancers, musicians, and guardian deities of the directions (Ashtadikpalas).', 'heritage', 20.2508, 85.8453, 'Situated on Tankapani Road in Old Town, Bhubaneswar. Readily accessible by cab or auto-rickshaw from city center.', 'Open daily sunrise to sunset. ASI ticketed monument: ₹25 for Indian nationals, ₹300 for foreign visitors. Beautifully maintained lawn gardens surrounding the temple. Host to the prestigious Rajarani Music Festival in January celebrating Indian classical music. Last verified: October 2026.', None, 'https://odishatourism.gov.in/en/w/rajarani-temple', place_image('rajarani-temple')),
        (125, 28, 'nandankanan-zoological-park', 'Nandankanan Zoological Park & Botanical Garden', 'A premier 437-hectare biological sanctuary nestled in the moist deciduous forests along the scenic Kanjia Lake. World-renowned as the first zoo in the world to breed white tigers and melanistic leopards in captivity, housing over 3,000 animals across 157 species. Features open safari drives (lion, tiger, bear, and herbivore), a ropeway across Kanjia Lake, and a botanical garden.', 'nature', 20.3956, 85.8239, 'Located 15 km north of Bhubaneswar city center. Accessible via Nandankanan Road by Mo Bus (Route 10), taxis, and auto-rickshaws.', 'Open Tuesday to Sunday 8:00 AM to 5:00 PM (closed on Mondays). Zoo entry: ₹50 for adults, ₹10 for children. Safaris and ropeway charged separately. Battery-operated vehicles and boating on Kanjia Lake available. Ideal for full-day family eco-tourism. Last verified: October 2026.', None, 'https://odishatourism.gov.in/en/w/nandankanan-zoological-park', place_image('nandankanan-zoological-park')),
        (126, 27, 'raghurajpur-craft-village', 'Raghurajpur Heritage Craft Village', 'A UNESCO-recognized historic heritage crafts village near Puri, nestled amidst groves of coconut, palm, and betelnut trees. Every household in this living open-air gallery is an artisan family dedicated to ancient Odisha crafts—most notably traditional Pattachitra cloth scroll paintings, palm-leaf engraving (Tala Pattachitra), wooden masks, cowdung toys, and the classical Gotipua dance (precursor to Odissi).', 'culture', 19.8653, 85.8219, 'Located 14 km from Puri town and 50 km from Bhubaneswar along the Bhubaneswar-Puri National Highway (NH-316). Accessible by auto-rickshaw or taxi.', 'Open daily 8:00 AM to 7:00 PM. No entry fee. Visitors can walk into artisans\' home-studios, watch masters paint with natural stone pigments, and purchase directly from National Award-winning craftspeople. Gotipua dance performances can be arranged on request. Last verified: October 2026.', None, 'https://odishatourism.gov.in/en/w/raghurajpur-craft-village', place_image('raghurajpur-craft-village')),
        (127, 27, 'pipili', 'Pipili Applique Craft Town', 'A world-renowned heritage artisan town on the highway between Bhubaneswar and Puri, famous for over eight centuries of vibrant Applique (Chandua) needlework craft. Originally patronized by the Gajapati kings of Puri to create ceremonial canopies, umbrellas (Chhatri), and banners for Lord Jagannath’s annual Rath Yatra festival. The main street is a dazzling corridor of lanterns, garden umbrellas, wall hangings, and bags.', 'culture', 20.1167, 85.8333, 'Located 20 km south of Bhubaneswar and 40 km north of Puri on NH-316. Convenient stopping point on the drive between Bhubaneswar and Puri.', 'Open daily 9:00 AM to 9:00 PM. Free entry. The roadside bazaar features hundreds of artisan shops displaying colorful appliquéd textiles. Excellent place to pick up authentic GI-tagged Odishan textile craft. Last verified: October 2026.', None, 'https://odishatourism.gov.in/en/w/pipili', place_image('pipili')),
        (128, 27, 'puri-golden-beach', 'Puri Golden Beach (Blue Flag Certified Beach)', 'One of India’s premier Blue Flag certified pristine beaches, stretching along the Bay of Bengal coastline of holy Puri. Celebrated for sparkling golden sands, clean swimming waters, seaside cycle tracks, high eco-tourism standards, and lifeguarded safe-bathing zones. Every evening, master sand artists, led by Padma Shri Sudarsan Pattnaik, sculpt monumental sand art on the shoreline.', 'beach', 19.7942, 85.8258, 'Located along the Marine Drive road in Puri town, 2 km from Puri Railway Station and within walking distance from hotels.', 'Open daily 5:00 AM to 9:00 PM. Blue Flag zone entry: ₹20–₹50 (includes beach loungers, clean showers, and changing facilities). Life jackets and lifeguard surveillance provided. Holy dip during sunrise and evening beach stalls for fried fish and chaat. Last verified: October 2026.', None, 'https://odishatourism.gov.in/en/w/puri-blue-flag-beach', place_image('puri-golden-beach')),
        (129, 27, 'chandrabhaga-beach', 'Chandrabhaga Beach, Konark', 'A sacred and breathtaking oceanfront beach located 3 km east of the Sun Temple at Konark along the Marine Drive. Revered in Hindu puranas as the place where Samba was cured of leprosy after worshipping Surya, it is famous for the auspicious Magha Saptami holy dip at dawn, tranquil golden sands, and hosting the grand International Sand Art Festival every December.', 'beach', 19.8650, 86.1083, 'Located 3 km from Konark Sun Temple and 32 km from Puri via the scenic Konark-Puri Marine Drive highway.', 'Open 24 hours daily. Free entry. The sunrise over the Bay of Bengal at Chandrabhaga is one of the most photographed seascapes in Eastern India. Swimming requires caution due to strong undercurrents. Last verified: October 2026.', None, 'https://odishatourism.gov.in/en/w/chandrabhaga-beach', place_image('chandrabhaga-beach')),
        (130, 558, 'bhitarkanika-national-park', 'Bhitarkanika National Park & Mangrove Wetland', 'India’s second-largest mangrove ecosystem and a premier Ramsar wetland sanctuary, crisscrossed by tidal rivers, creeks, and mudflats. Shelters over 1,700 endangered saltwater crocodiles (including record 20-foot specimens), king cobras, water monitor lizards, and over 215 species of birds. The adjacent Gahirmatha beach is the world’s largest rookery for mass nesting (Arribada) of Olive Ridley sea turtles.', 'nature', 20.7258, 86.8711, 'Boat entry points are at Khola and Gupti (near Rajnagar/Pattamundai). Reached by road from Cuttack (130 km) or Bhubaneswar (160 km). Nearest railhead is Bhadrak (70 km).', 'UNESCO Tentative List. Park open 7:00 AM to 5:00 PM. Entry fee: ₹40 per Indian, ₹500 foreign visitors; boat hire ₹2,500–₹4,000 per boat. Note: Annual closure from May 1 to July 31 for crocodile breeding season. Eco-resorts and forest department cottages available at Dangmal. Last verified: October 2026.', 14, 'https://odishatourism.gov.in/en/w/bhitarkanika-national-park', place_image('bhitarkanika-national-park')),
        (131, 562, 'similipal-national-park', 'Similipal National Park & Biosphere Reserve', 'A vast, densely forested UNESCO World Biosphere Reserve spanning 2,750 square kilometers of towering sal trees, undulating hill ranges, and pristine grasslands. Home to the Royal Bengal tiger, rare melanistic (black) tigers, wild elephants, leopards, and over 1,000 species of plants. Features two of Eastern India’s most dramatic waterfalls—Barehipani (399 m, two-tiered) and Joranda (181 m).', 'nature', 21.9333, 86.3500, 'Entry gates at Pithabata (22 km from Baripada) and Jashipur (along NH-49). Reachable by road from Bhubaneswar (250 km) or Kolkata (240 km).', 'Open seasonally from November 1 to mid-June (strictly closed during monsoon). Entry permit: ₹100 per Indian, ₹1,000 foreign visitors; vehicle entry fee ₹200. Only 4x4 high-clearance vehicles allowed inside. Nature camps operated by Odisha Ecotourism at Barehipani, Gurguria, and Jamuani. Last verified: October 2026.', None, 'https://odishatourism.gov.in/en/w/similipal-national-park', place_image('similipal-national-park')),
        (132, 557, 'barabati-fort', 'Barabati Fort & Kataka Silver Filigree', 'A historic 14th-century fortress built by the Ganga dynasty on a deltaic promontory between the Mahanadi and Kathajodi rivers in the ancient Silver City of Cuttack. Encircled by a massive stone moat and defensive ramparts, it features an ornate carved stone gateway and the excavated foundation of a nine-story royal palace. Cuttack is celebrated globally for Tarakasi (exquisite fine silver filigree jewelry and miniature chariots).', 'heritage', 20.4853, 85.8647, 'Located in Bidanasi, Cuttack city center, 5 km from Cuttack Railway Station and 30 km from Bhubaneswar via NH-16.', 'Open daily sunrise to sunset. No entry fee. The adjacent Barabati Stadium hosts international cricket matches. Visit old bazaars in Nayasarak and Balu Bazaar to watch master Tarakasi silversmiths pull hair-thin silver wire into lace-like jewelry. Last verified: October 2026.', None, 'https://odishatourism.gov.in/en/w/barabati-fort', place_image('barabati-fort')),
        (133, 553, 'ratnagiri-monastery', 'Ratnagiri Buddhist Monastery (Diamond Triangle)', 'The most prominent gem of Odisha’s Buddhist "Diamond Triangle" (Ratnagiri, Udayagiri, and Lalitgiri). Flourishing between the 6th and 12th centuries as a premier center of Tantric Buddhism (Vajrayana), the site crowns an isolated hill overlooking the Birupa River, featuring a colossal sculpted monastery gateway carved with chlorite stone, a massive stone courtyard with a 12-foot seated Buddha, and hundreds of votive stupas.', 'heritage', 20.6408, 86.3353, 'Located in Jajpur district, 100 km northeast of Bhubaneswar and 70 km from Cuttack via NH-16. Accessible by taxi or private car.', 'ASI ticketed monument: ₹25 for Indian nationals, ₹300 for foreign visitors. Museum open 9:00 AM to 5:00 PM (closed Fridays). The green chlorite carved portal is widely considered one of the finest Buddhist architectural stone carvings in Asia. Last verified: October 2026.', None, 'https://odishatourism.gov.in/en/w/ratnagiri-monastery', place_image('ratnagiri-monastery')),
        (134, 560, 'deomali-hills', 'Deomali Hills & Highest Peak of Odisha', 'The highest mountain summit in Odisha, rising to an elevation of 1,672 metres (5,485 ft) in the Eastern Ghats near Semiliguda. Revered for rolling emerald-green hillocks, sweeping panoramic vistas of cloud-filled valleys, cool mountain breezes, indigenous tribal settlements (Kandha and Paraja), and developing adventure tourism including paragliding, trekking, and eco-cottage stays.', 'nature', 18.6667, 82.9833, 'Located 60 km from Koraput town and 35 km from Semiliguda. Accessible via winding scenic mountain roads by taxi, SUV, or rented vehicle.', 'Open all hours. Free entry. Eco-tourism cottages and glamping tents operated by Odisha Tourism are available atop the ridge. Best visited at dawn to witness sunrise over the sea of clouds and in winter when temperatures dip below 5°C. Last verified: October 2026.', None, 'https://odishatourism.gov.in/en/w/deomali-hills', place_image('deomali-hills')),
        (135, 560, 'duduma-waterfall', 'Duduma Waterfall & Machkund Gorge', 'One of India’s most spectacular horsetail waterfalls, plunging 175 metres (574 ft) down the sheer granite cliffs of the Eastern Ghats into the deep Machkund River gorge along the Odisha-Andhra Pradesh border. Surrounded by dense virgin subtropical forests, this thunderous cascade powers the Machkund Hydroelectric Project and is located near the homeland of the indigenous Bonda tribal community.', 'nature', 18.5167, 82.5333, 'Located near Onukudelli, 70 km southwest of Koraput town. Reached by road via Lamtaput.', 'Open daily sunrise to sunset. No entry fee. Viewing platforms provide panoramic angles of the roaring waterfall and gorge. Thursday is the famous weekly market (haat) at nearby Onukudelli where the Bonda and Gadaba tribal communities gather. Last verified: October 2026.', None, 'https://odishatourism.gov.in/en/w/duduma-waterfall', place_image('duduma-waterfall')),
        (136, 560, 'gupteswar-cave', 'Gupteswar Cave Temple, Kolab Valley', 'A sacred natural limestone cave sanctuary tucked inside the dense forest hills of the Ramagiri range along the Kolab River. Meaning "The Hidden God", the subterranean cavern contains an imposing 2-metre-high natural stalagmite Shiva Lingam that is believed to increase in size annually, deeply revered by local indigenous tribes and pilgrims during Shravan and Maha Shivratri.', 'spiritual', 18.8167, 82.2333, 'Located 55 km from Jeypore and 80 km from Koraput. Reached by road through scenic forested rural routes.', 'Open daily 6:00 AM to 7:00 PM. Free entry. Walking involves climbing stone steps down into the limestone cave entrance. Carry torches for exploring deeper chambers. Monkeys roam outside—safeguard offerings. Last verified: October 2026.', None, 'https://odishatourism.gov.in/en/w/gupteswar-cave-temple', place_image('gupteswar-cave')),
        (137, 550, 'padma-sambhava-maha-vihara', 'Padma Sambhava Maha Vihara, Jirango', 'The largest Tibetan Buddhist monastery in Eastern India, inaugurated in 2010 by His Holiness the 14th Dalai Lama in the peaceful Tibetan refugee settlement of Chandragiri (Phuntsokling). Rising five stories high amidst mist-shrouded green hills, the grand monastery features a 23-foot bronze statue of Buddha Shakyamuni, vibrant frescoes depicting Buddhist deities, a golden prayer wheel gallery, and a monastic college.', 'spiritual', 19.3417, 84.2611, 'Located in Chandragiri/Jirang, 80 km from Berhampur in southern Odisha. Easily accessible by private taxi or state bus via Digapahandi and Mohana.', 'Open daily 6:00 AM to 6:00 PM. Free entry. Modest attire required inside the main prayer hall. The settlement produces authentic Tibetan hand-knotted woollen carpets, dried fruits, and organic maize. Last verified: October 2026.', None, 'https://odishatourism.gov.in/en/w/padma-sambhava-maha-vihara-monastery-jirango', place_image('padma-sambhava-maha-vihara')),
        (138, 556, 'daringbadi-hill-station', 'Daringbadi Hill Station (Kashmir of Odisha)', 'Known as the "Kashmir of Odisha", Daringbadi is a serene hill station perched at 915 metres (3,000 ft) amidst lush pine forests, organic coffee and black pepper plantations, and misty mountain valleys. It is the only place in Odisha where temperatures drop below freezing and morning frost coats the landscape in deep winter, offering viewpoints like Hill View Park, Midubanda waterfall, and emu farms.', 'nature', 19.9083, 84.1333, 'Located in Kandhamal district, 125 km from Berhampur and 250 km from Bhubaneswar. Connected by winding scenic ghat roads.', 'Open year-round; peak winter season from November to February brings chilly weather and morning mist. Eco-retreat glamping and tribal homestays operate in winter. Organic coffee, pure turmeric, and wild forest honey available directly from local cooperatives. Last verified: October 2026.', None, 'https://odishatourism.gov.in/en/w/daringbadi-hill-station', place_image('daringbadi-hill-station')),
        (139, 551, 'gopalpur-sea-beach', 'Gopalpur-on-Sea & Tampara Lake', 'A charming, unhurried seaside resort on the Bay of Bengal, Gopalpur flourished in colonial times as a thriving seaport trading with Burma and Southeast Asia. Features clean sandy beaches, the weathered stone ruins of ancient port jetties, an 1871 operational lighthouse, and watersports and speedboating at nearby Tampara Lake (a scenic 300-hectare freshwater lagoon).', 'beach', 19.2667, 84.9000, 'Located 16 km from Berhampur city and railway station, directly accessible by auto-rickshaw, city bus, or taxi along the four-lane highway.', 'Open all hours. Free beach access. Lighthouse open for viewing 3:30 PM to 5:30 PM (₹10 entry). Calm waters for walking along the surf. Freshly fried coastal seafood and cashew nuts sold at beachfront shacks. Last verified: October 2026.', None, 'https://odishatourism.gov.in/en/w/gopalpur-sea-beach', place_image('gopalpur-sea-beach')),
        (140, 551, 'tara-tarini-temple', 'Tara Tarini Temple (Adi Shakti Peetha)', 'One of India’s four ancient Adi Shakti Peethas (representing the Sthana Peetha or breasts of Goddess Sati), perched atop the scenic 708-foot Purnagiri Hill overlooking the Rushikulya River. The ancient shrine houses two stone deities—Maa Tara and Maa Tarini—revered as the patron goddesses of ancient Kalinga seafarers. The summit is reached via 999 stone steps, a winding hill road, or a modern passenger ropeway.', 'spiritual', 19.4933, 84.8967, 'Located near Purushottampur in Ganjam district, 32 km from Berhampur. Connected by state buses and private taxis.', 'Open daily 5:30 AM to 12:30 PM and 2:00 PM to 8:30 PM. Free temple entry; ropeway cable car costs ₹70 per person return. The Chaitra Mela on Tuesdays in March/April is one of Odisha’s largest religious congregations. Last verified: October 2026.', None, 'https://odishatourism.gov.in/en/w/tara-tarini-temple', place_image('tara-tarini-temple')),
        (141, 567, 'hirakud-dam', 'Hirakud Dam & Reservoir (Gandhi & Nehru Minars)', 'Built across the mighty Mahanadi River in 1957, Hirakud is one of the longest major earthen dams in the world, spanning 25.8 kilometers including its dykes. Creates a monumental 743-square-kilometer artificial reservoir that forms an inland sea. Visitors can enjoy panoramic views of the water expanse and surrounding hills from two observation towers—Gandhi Minar on the south hill and Nehru Minar on the north.', 'nature', 21.5200, 83.8700, 'Located 15 km north of Sambalpur city center. Easily accessible by taxi, auto-rickshaw, or local bus from Sambalpur or Burla.', 'Observation towers open daily 9:00 AM to 5:30 PM. Nominal entry fee of ₹10–₹20. Sunset over the vast reservoir from Gandhi Minar is spectacular. Boating on the reservoir and eco-retreat luxury glamping operate in winter. Last verified: October 2026.', None, 'https://odishatourism.gov.in/en/w/hirakud-dam', place_image('hirakud-dam')),
        (142, 567, 'maa-samaleswari-temple', 'Maa Samaleswari Temple, Sambalpur', 'The revered 16th-century riverbank temple of Goddess Samaleswari, the presiding deity of Western Odisha and Sambalpur. Built by King Balaram Dev on the banks of the Mahanadi, the shrine is constructed of stone in traditional Chauka architectural style with a sprawling mandapa. It is the spiritual epicenter of the grand Nuakhai harvest festival, when the first harvest of paddy is offered to the Goddess.', 'spiritual', 21.4642, 83.9667, 'Located in Khetrajpur, Sambalpur, 2 km from Sambalpur Railway Station. Easily reached on foot, auto-rickshaw, or cycle-rickshaw.', 'Open daily 5:00 AM to 12:00 PM and 4:00 PM to 8:30 PM. Free entry. The recently completed SAMALEI project has created a grand heritage riverfront corridor, park, and evening lightings. Sambalpuri Ikat handloom stores are located nearby. Last verified: October 2026.', None, 'https://odishatourism.gov.in/en/w/maa-samaleswari-temple', place_image('maa-samaleswari-temple')),
        (143, 544, 'chandipur-beach', 'Chandipur Beach (The Vanishing Sea)', 'A unique coastal wonder on the Bay of Bengal in northern Odisha, where the sea recedes up to 5 kilometers during low tide twice every day, revealing a vast, flat expanse of the seabed where visitors can walk, ride bicycles, and spot red ghost crabs and horseshoe crabs. When high tide rolls in, the waters rush back to lap against the tranquil casuarina-lined shoreline.', 'beach', 21.4667, 87.0167, 'Located 16 km from Balasore city and railway station (connected to the Kolkata-Chennai mainline). Easily reachable by auto-rickshaw or taxi.', 'Open 24 hours. Free entry. Always observe local tide tables before venturing far out onto the exposed seabed, and return before high tide begins. Fresh fried coastal seafood and soft green coconuts sold by local beach vendors. Last verified: October 2026.', None, 'https://odishatourism.gov.in/en/w/chandipur-beach', place_image('chandipur-beach')),
        (144, 564, 'satkosia-gorge', 'Satkosia Gorge Sanctuary & Mahanadi Eco-Camps', 'A monumental natural spectacle where the mighty Mahanadi River carves a dramatic 22-kilometer-long gorge through the dense sal and teak forests of the Eastern Ghats. Sheltering the Satkosia Tiger Reserve, the gorge is one of India’s premier sanctuaries for the endangered freshwater gharial and mugger crocodiles, hornbills, and leopards. Visitors experience deep canyon boat safaris and tented riverbank eco-camps.', 'nature', 20.5833, 84.8667, 'Major access points are at Tikarpada (via Angul, 60 km) and Chhotkei / Badmul (via Nayagarh, 75 km from Bhubaneswar).', 'Sanctuary open 7:00 AM to 5:00 PM (safaris and camping operate October to May; boat safaris suspended during monsoon). Entry fee: ₹40 per person; boat safaris ₹1,500–₹2,500. Eco-resorts with Swiss luxury tents operated by Odisha Ecotourism at Badmul and Tikarpada. Last verified: October 2026.', None, 'https://odishatourism.gov.in/en/w/satkosia-gorge-tiger-reserve', place_image('satkosia-gorge')),
    ]
    odisha_json_path = ROOT / 'data' / 'odisha-places.json'
    odisha_extra = []
    if odisha_json_path.exists():
        odisha_extra = json.loads(odisha_json_path.read_text(encoding='utf-8'))
        for op in odisha_extra:
            places.append((
                op['id'], op['district_id'], op['slug'], op['name'], op['description'],
                op['category'], op['latitude'], op['longitude'], op['how_to_reach'],
                op['practical_notes'], op['heritage_id'], op['source_url'],
                place_image(op['slug'])
            ))
    db.executemany('''INSERT OR IGNORE INTO places
        (id,district_id,slug,name,description,category,latitude,longitude,how_to_reach,practical_notes,heritage_id,source_url,image_url)
        VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?)''', places)
    db.executemany('UPDATE places SET image_url=? WHERE id=?', [(p[12], p[0]) for p in places])
    # Odisha records are sourced from a maintained JSON dataset. Update existing
    # rows too so corrections are applied to databases created by earlier releases.
    if odisha_extra:
        db.executemany('''UPDATE places SET
                district_id=?, name=?, description=?, category=?, latitude=?, longitude=?,
                how_to_reach=?, practical_notes=?, heritage_id=?, source_url=?, image_url=?
            WHERE slug=?''', [
                (
                    op['district_id'], op['name'], op['description'], op['category'],
                    op['latitude'], op['longitude'], op['how_to_reach'],
                    op['practical_notes'], op['heritage_id'], op['source_url'],
                    place_image(op['slug']), op['slug'],
                )
                for op in odisha_extra
            ])

